import sys
def compress(data, maxbits=16, block=True):
    out=bytearray([0x1f,0x9d,(maxbits | (0x80 if block else 0))])
    bits=9; maxcode=(1<<bits)-1
    dic={bytes([i]):i for i in range(256)}
    nxt=257 if block else 256
    buf=0; nb=0
    codes=[]  # (code,bits)
    # emulate compress(1) bit packing with group flushing on bit width change
    group=[]
    res=bytearray()
    def flush_group(g, bits):
        # pack codes in group of bits width; pad to multiple of bits bytes
        acc=0; n=0; b=bytearray()
        for c in g:
            acc |= c<<n; n+=bits
            while n>=8:
                b.append(acc&255); acc>>=8; n-=8
        if n>0: b.append(acc&255)
        return b
    w=b''
    curbits=9
    pending=[]
    i=0
    def emit(code):
        nonlocal curbits, pending
        pending.append(code)
    out_codes=[]
    for ch in data:
        wc=w+bytes([ch])
        if wc in dic:
            w=wc
        else:
            out_codes.append((dic[w],curbits))
            if nxt < (1<<maxbits):
                dic[wc]=nxt; nxt+=1
                if nxt > (1<<curbits) and curbits<maxbits:
                    out_codes.append(('W',curbits+1)); curbits+=1
            w=bytes([ch])
    if w: out_codes.append((dic[w],curbits))
    # pack: when width changes, pad the previous group to a multiple of 'bits' bytes (compress(1) behavior)
    res=bytearray(); grp=[]; gb=9
    for c,b in out_codes:
        if c=='W':
            chunk=flush_group(grp,gb)
            # pad to multiple of gb bytes counted from group start
            nbytes=len(grp)*gb
            # compress(1) pads groups: total bytes rounded up to multiple of gb
            full=((len(grp)+7)//8)*gb
            chunk=chunk+bytes(full-len(chunk))
            res+=chunk; grp=[]; gb=b
        else:
            grp.append(c)
    res+=flush_group(grp,gb)
    return bytes(out)+bytes(res)
if __name__=='__main__':
    d=sys.stdin.buffer.read()
    sys.stdout.buffer.write(compress(d))
