/* pz.h -- shared declarations for the parallel gzip work-alike */
#ifndef PZ_H
#define PZ_H

#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>
#include <time.h>
#include "zop/zop.h"

#define WINSZ 32768U            /* deflate history window / dictionary size */

/* program-wide settings and per-file state */
struct settings {
    /* invocation */
    const char *prog;           /* program name for messages */
    int ret;                    /* exit status to return */

    /* options */
    int level;                  /* compression level 0..9, 11 */
    int strategy;               /* zlib strategy */
    int form;                   /* 0 gzip, 1 zlib, 2 zip (3 zip+desc when reading) */
    const char *sufx;           /* suffix for compressed output */
    int headis;                 /* header store/restore bits */
    int decode;                 /* 0 compress, 1 decompress, 2 test */
    int list;                   /* list contents */
    int pipeout;                /* write to stdout */
    int force;
    int keep;
    int recurse;
    int verbosity;
    int procs;                  /* maximum compression threads */
    size_t block;               /* input block size */
    int rsync;
    int setdict;                /* use previous block as dictionary */
    int sync;                   /* fsync output */
    const char *alias;          /* zip name for stdin */
    const char *comment;        /* header comment */
    ZopOptions zopts;           /* level 11 parameters */

    /* current file */
    char *inf;                  /* input file name */
    size_t infsz;
    char *outf;                 /* output file name, NULL if none */
    int ind;                    /* input descriptor */
    int outd;                   /* output descriptor, -1 if none */
    const char *name;           /* name to store in header, or NULL */
    time_t mtime;               /* time to store in header */

    /* information from a header read when decoding */
    char *hname;                /* stored name, or NULL */
    char *hcomm;                /* stored comment, or NULL */
    time_t stamp;               /* stored modification time */
    unsigned long zip_crc;
    uint64_t zip_clen, zip_ulen;
    int first;                  /* true until list heading printed */
};
extern struct settings g;

/* messages and errors */
void complain(const char *fmt, ...);
void bail(int code, const char *fmt, ...);
void *xmalloc(size_t n);
void *xrealloc(void *p, size_t n);
char *xstrdup(const char *s);

/* raw output */
void out_write(int fd, const void *buf, size_t len);
size_t in_read(int fd, void *buf, size_t len);

/* compression */
void compress_single(void);
void compress_parallel(void);

/* decompression and listing (operate on g.ind) */
void in_begin(void);
void in_finish(void);
int read_header(int save);
void inflate_check(void);
void lzw_expand(void);
void copy_through(void);
void list_info(void);
void show_info(int method, unsigned long check, int64_t len, int cont);
extern int64_t in_total;        /* compressed byte count bookkeeping */
extern int64_t out_total;

#endif
EOF"}

