/* main.c -- command line handling and per-file processing */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <errno.h>
#include <limits.h>
#include <unistd.h>
#include <fcntl.h>
#include <dirent.h>
#include <setjmp.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <zlib.h>
#include "pz.h"

struct settings g;

/* ---- messages ---------------------------------------------------------- */

void complain(const char *fmt, ...)
{
    va_list ap;
    if (g.verbosity > 0) {
        fprintf(stderr, "%s: ", g.prog);
        va_start(ap, fmt);
        vfprintf(stderr, fmt, ap);
        va_end(ap);
        putc('\n', stderr);
        fflush(stderr);
    }
    g.ret = 1;
}

/* remove a partially written output file */
static void drop_output(void)
{
    if (g.outd != -1 && g.outd != 1) {
        close(g.outd);
        g.outd = -1;
        if (g.outf != NULL)
            unlink(g.outf);
    }
}

void bail(int code, const char *fmt, ...)
{
    va_list ap;
    if (g.verbosity > 0) {
        fprintf(stderr, "%s: abort: ", g.prog);
        va_start(ap, fmt);
        vfprintf(stderr, fmt, ap);
        va_end(ap);
        putc('\n', stderr);
        fflush(stderr);
    }
    drop_output();
    fflush(stdout);
    _exit(code);
}

void *xmalloc(size_t n)
{
    void *p = malloc(n ? n : 1);
    if (p == NULL)
        bail(ENOMEM, "not enough memory");
    return p;
}

void *xrealloc(void *p, size_t n)
{
    p = realloc(p, n ? n : 1);
    if (p == NULL)
        bail(ENOMEM, "not enough memory");
    return p;
}

char *xstrdup(const char *s)
{
    size_t n = strlen(s) + 1;
    char *d = xmalloc(n);
    memcpy(d, s, n);
    return d;
}

/* ---- raw i/o ----------------------------------------------------------- */

void out_write(int fd, const void *buf, size_t len)
{
    const unsigned char *p = buf;
    while (len) {
        size_t chunk = len > 1U << 30 ? 1U << 30 : len;
        ssize_t n = write(fd, p, chunk);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            bail(errno, "write error on %s (%s)",
                 g.outf == NULL ? "<stdout>" : g.outf, strerror(errno));
        }
        p += n;
        len -= (size_t)n;
    }
}

size_t in_read(int fd, void *buf, size_t len)
{
    unsigned char *p = buf;
    size_t got = 0;
    while (len) {
        size_t chunk = len > 1U << 30 ? 1U << 30 : len;
        ssize_t n = read(fd, p, chunk);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            bail(errno, "read error on %s (%s)", g.inf, strerror(errno));
        }
        if (n == 0)
            break;
        p += n;
        got += (size_t)n;
        len -= (size_t)n;
    }
    return got;
}

/* ---- help and version ------------------------------------------------- */

static const char *helptext[] = {
