static void show_help(void)
{
    int i;
    if (g.verbosity == 0)
        return;
    for (i = 0; helptext[i] != NULL; i++)
        fprintf(stderr, "%s\n", helptext[i]);
    fflush(stderr);
    exit(0);
}

/* ---- option parsing --------------------------------------------------- */

static const struct { const char *lng; char shrt; } longs[] = {
    {"LZW", 'Z'}, {"lzw", 'Z'}, {"alias", 'A'}, {"ascii", 'a'},
    {"best", '9'}, {"bits", 'Z'}, {"blocksize", 'b'}, {"decompress", 'd'},
    {"fast", '1'}, {"force", 'f'}, {"comment", 'C'}, {"first", 'F'},
    {"iterations", 'I'}, {"maxsplits", 'J'}, {"oneblock", 'O'},
    {"help", 'h'}, {"independent", 'i'}, {"keep", 'k'}, {"license", 'L'},
    {"list", 'l'}, {"name", 'N'}, {"no-name", 'n'}, {"no-time", 'm'},
    {"processes", 'p'}, {"quiet", 'q'}, {"recursive", 'r'},
    {"rsyncable", 'R'}, {"silent", 'q'}, {"stdout", 'c'}, {"suffix", 'S'},
    {"synchronous", 'Y'}, {"test", 't'}, {"time", 'M'}, {"to-stdout", 'c'},
    {"uncompress", 'd'}, {"verbose", 'v'}, {"version", 'V'}, {"zip", 'K'},
    {"zlib", 'z'}, {"huffman", 'H'}, {"rle", 'U'}, {NULL, 0}
};

/* parse a decimal number for an option parameter */
static size_t parse_num(const char *arg)
{
    const char *s = arg;
    size_t val = 0;
    if (*s == 0)
        bail(EINVAL, "internal error: empty parameter");
    do {
        unsigned d = (unsigned char)*s - '0';
        if (d > 9 || (val && (SIZE_MAX - d) / val < 10))
            bail(EINVAL, "invalid numeric parameter: %s", arg);
        val = val * 10 + d;
    } while (*++s);
    return val;
}

static int want;                /* option letter awaiting a parameter, or 0 */

static void take_param(const char *arg)
{
    size_t n;
    switch (want) {
    case 'b':
        n = parse_num(arg);
        g.block = n << 10;
        if (g.block < WINSZ)
            bail(EINVAL, "block size too small (must be >= 32K)");
        if (n != g.block >> 10 || g.block > (1UL << 29))
            bail(EINVAL, "block size too large: %s", arg);
        break;
    case 'p':
        n = parse_num(arg);
        g.procs = (int)n;
        if (g.procs < 1)
            bail(EINVAL, "invalid number of processes: %s", arg);
        if ((size_t)g.procs != n || g.procs > INT_MAX / 2 - 2)
            bail(EINVAL, "too many processes: %s", arg);
        break;
    case 'S':
        if (*arg == 0)
            bail(EINVAL, "suffix cannot be empty");
        g.sufx = arg;
        break;
    case 'I':
        g.zopts.numiterations = (int)parse_num(arg);
        break;
    case 'J':
        g.zopts.blocksplittingmax = (int)parse_num(arg);
        break;
    case 'A':
        g.alias = arg;
        break;
    case 'C':
        g.comment = arg;
        break;
    }
    want = 0;
}

/* process one argument (or NULL to check for a missing parameter) --
   return true if arg is a file name to process later */
static int option(const char *arg)
{
    if (want && (arg == NULL || *arg == '-'))
        bail(EINVAL, "missing parameter after -%c", want);
    if (arg == NULL)
        return 1;

    if (*arg == '-') {
        const char *p = arg + 1;
        char shortbuf[2];
        if (*p == 0)
            return 1;               /* "-" means stdin */
        if (*p == '-') {            /* long option */
            int j;
            for (j = 0; longs[j].lng != NULL; j++)
                if (strcmp(p + 1, longs[j].lng) == 0)
                    break;
            if (longs[j].lng == NULL)
                bail(EINVAL, "invalid option: %s", arg);
            shortbuf[0] = longs[j].shrt;
            shortbuf[1] = 0;
            p = shortbuf;
        }
        do {
            if (want) {
                if (want == 'S')
                    bail(EINVAL, "invalid usage: -S must be followed by space");
                break;              /* rest of argument is the parameter */
            }
            switch (*p) {
            case '0': case '1': case '2': case '3': case '4':
            case '5': case '6': case '7': case '8': case '9':
                g.level = *p - '0';
                while (p[1] >= '0' && p[1] <= '9') {
                    if (g.level && (INT_MAX - (p[1] - '0')) / g.level < 10)
                        bail(EINVAL, "only levels 0..9 and 11 are allowed");
                    g.level = g.level * 10 + *++p - '0';
                }
                if (g.level == 10 || g.level > 11)
                    bail(EINVAL, "only levels 0..9 and 11 are allowed");
                break;
            case 'A': case 'C': case 'I': case 'J': case 'S': case 'b':
            case 'p':
                want = *p;
                break;
            case 'F': g.zopts.blocksplittinglast = 1; break;
            case 'K': g.form = 2; g.sufx = ".zip"; break;
            case 'L':
                puts("pigz 2.8");
                puts("Copyright (C) 2007-2023 Mark Adler");
                puts("Subject to the terms of the zlib license.");
                puts("No warranty is provided or implied.");
                exit(0);
            case 'M': g.headis |= 0xa; break;
            case 'N': g.headis = 0xf; break;
            case 'O': g.zopts.blocksplitting = 0; break;
            case 'R': g.rsync = 1; break;
            case 'V':
                puts("pigz 2.8");
                if (g.verbosity > 1)
                    printf("zlib %s\n", zlibVersion());
                exit(0);
            case 'Y': g.sync = 1; break;
            case 'Z':
                bail(EINVAL, "invalid option: LZW output not supported: -%c",
                     *p);
                break;
            case 'a':
                bail(EINVAL, "invalid option: no ascii conversion: -%c", *p);
                break;
            case 'c': g.pipeout = 1; break;
            case 'd':
                if (!g.decode)
                    g.headis >>= 2;
                g.decode = 1;
                break;
            case 'f': g.force = 1; break;
            case 'h': show_help(); break;
            case 'i': g.setdict = 0; break;
            case 'k': g.keep = 1; break;
            case 'l': g.list = 1; break;
            case 'n': g.headis = 0; break;
            case 'T':
            case 'm': g.headis &= ~0xa; break;
            case 'q': g.verbosity = 0; break;
            case 'r': g.recurse = 1; break;
            case 't': g.decode = 2; break;
            case 'U': g.strategy = Z_RLE; break;
            case 'H': g.strategy = Z_HUFFMAN_ONLY; break;
            case 'v': g.verbosity++; break;
            case 'z': g.form = 1; g.sufx = ".zz"; break;
            default:
                bail(EINVAL, "invalid option: -%c", *p);
            }
        } while (*++p);
        if (*p == 0)
            return 0;
        arg = p;
    }

    if (want) {
        take_param(arg);
        return 0;
    }
    return 1;
}

/* process options in an environment variable */
static void env_options(const char *var)
{
    char *val = getenv(var), *copy, *p, *q;
    if (val == NULL)
        return;
    copy = xstrdup(val);
    p = copy;
    while (*p) {
        while (*p == ' ' || *p == '\t')
            p++;
        q = p;
        while (*q && *q != ' ' && *q != '\t')
            q++;
        if (*q)
            *q++ = 0;
        if (option(p))
            bail(EINVAL, "cannot provide files in %s environment variable",
                 var);
        p = q;
    }
    option(NULL);
    /* copy is intentionally kept: parameters may point into it */
}

/* ---- file name helpers ------------------------------------------------ */

static const char *basename_of(const char *path)
{
    const char *p = strrchr(path, '/');
    return p == NULL ? path : p + 1;
}

/* length of a recognized compressed suffix at the end of nm, or 0 */
static size_t suffix_len(const char *nm)
{
    size_t len = strlen(nm);
    if (len > 4) {
        const char *s = nm + len - 4;
        if (!strcmp(s, ".zip") || !strcmp(s, ".ZIP") || !strcmp(s, ".tgz"))
            return 4;
    }
    if (len > 3) {
        const char *s = nm + len - 3;
        if (!strcmp(s, ".gz") || !strcmp(s, "-gz") || !strcmp(s, ".zz") ||
            !strcmp(s, "-zz"))
            return 3;
    }
    if (len > 2) {
        const char *s = nm + len - 2;
        if (!strcmp(s, ".z") || !strcmp(s, "-z") || !strcmp(s, "_z") ||
            !strcmp(s, ".Z"))
            return 2;
    }
    return 0;
}
size_t pz_suffix_len(const char *nm) { return suffix_len(nm); }

static void set_inf(const char *s, size_t at)
{
    size_t n = strlen(s);
    if (at + n + 1 > g.infsz) {
        g.infsz = at + n + 1 + 64;
        g.inf = xrealloc(g.inf, g.infsz);
    }
    memcpy(g.inf + at, s, n + 1);
}

/* copy permissions, owner, and times from one file to another */
static void copy_meta(const char *from, const char *to)
{
    struct stat st;
    struct timeval tv[2];
    if (stat(from, &st) != 0 || !S_ISREG(st.st_mode))
        return;
    (void)chmod(to, st.st_mode & 07777);
    (void)!chown(to, st.st_uid, st.st_gid);
    tv[0].tv_sec = st.st_atime;
    tv[0].tv_usec = 0;
    tv[1].tv_sec = st.st_mtime;
    tv[1].tv_usec = 0;
    (void)utimes(to, tv);
}

static void set_times(const char *path, time_t t)
{
    struct timeval tv[2];
    tv[0].tv_sec = t;
    tv[0].tv_usec = 0;
    tv[1].tv_sec = t;
    tv[1].tv_usec = 0;
    (void)utimes(path, tv);
}

/* ---- error recovery for corrupt input ---------------------------------- */

jmp_buf pz_corrupt_jump;
char pz_corrupt_msg[8192];

/* ---- process one file -------------------------------------------------- */

static void process(const char *path)
{
    int method = -1;
    size_t len;
    struct stat st;
    static const char *sufs[] = {".z", "-z", "_z", ".Z", ".gz", "-gz", ".zz",
                                 "-zz", ".zip", ".ZIP", ".tgz", NULL};

    memset(&st, 0, sizeof(st));
    if (path == NULL) {
        set_inf("<stdin>", 0);
        g.ind = 0;
        g.name = NULL;
        g.mtime = 0;
        if (g.headis & 2) {
            struct stat sst;
            if (fstat(0, &sst) == 0 && S_ISREG(sst.st_mode))
                g.mtime = sst.st_mtime;
        }
        len = 0;
    }
    else {
        if (path != g.inf)
            set_inf(path, 0);
        len = strlen(g.inf);

        if (lstat(g.inf, &st)) {
            if (errno == ENOENT && (g.list || g.decode)) {
                const char **s = sufs;
                do {
                    if (*s == NULL)
                        break;
                    set_inf(*s++, len);
                    errno = 0;
                } while (lstat(g.inf, &st) && errno == ENOENT);
            }
            if (errno) {
                g.inf[len] = 0;
                complain("skipping: %s does not exist", g.inf);
                return;
            }
            len = strlen(g.inf);
        }

        if (!S_ISREG(st.st_mode) && !S_ISFIFO(st.st_mode) &&
            !S_ISLNK(st.st_mode) && !S_ISDIR(st.st_mode)) {
            complain("skipping: %s is a special file or device", g.inf);
            return;
        }
        if (S_ISLNK(st.st_mode) && !g.force && !g.pipeout) {
            complain("skipping: %s is a symbolic link", g.inf);
            return;
        }
        if (S_ISDIR(st.st_mode) && !g.recurse) {
            complain("skipping: %s is a directory", g.inf);
            return;
        }

        if (S_ISDIR(st.st_mode)) {
            DIR *dir;
            struct dirent *ent;
            char *names = NULL;
            size_t used = 0, room = 0, off, base;

            dir = opendir(g.inf);
            if (dir == NULL)
                return;
            while ((ent = readdir(dir)) != NULL) {
                const char *nm = ent->d_name;
                size_t n;
                if (nm[0] == 0 || (nm[0] == '.' && (nm[1] == 0 ||
                    (nm[1] == '.' && nm[2] == 0))))
                    continue;
                n = strlen(nm) + 1;
                if (used + n + 1 > room) {
                    room = (used + n + 1) * 2;
                    names = xrealloc(names, room);
                }
                memcpy(names + used, nm, n);
                used += n;
            }
            closedir(dir);
            if (names == NULL)
                return;
            names[used] = 0;

            if (len && g.inf[len - 1] != '/') {
                set_inf("/", len);
                base = len + 1;
            }
            else
                base = len;
            for (off = 0; names[off]; off += strlen(names + off) + 1) {
                set_inf(names + off, base);
                process(g.inf);
            }
            g.inf[len] = 0;
            free(names);
            return;
        }

        if (!(g.force || g.list || g.decode) && len >= strlen(g.sufx) &&
            strcmp(g.inf + len - strlen(g.sufx), g.sufx) == 0) {
            if (g.verbosity > 0) {
                fprintf(stderr, "%s: skipping: %s ends with %s\n", g.prog,
                        g.inf, g.sufx);
                fflush(stderr);
            }
            return;
        }

        if (g.decode == 1 && !g.pipeout && !g.list) {
            size_t suf = suffix_len(g.inf);
            if (suf == 0) {
                complain("skipping: %s does not have compressed suffix",
                         g.inf);
                return;
            }
            len -= suf;
        }

        g.ind = open(g.inf, O_RDONLY, 0);
        if (g.ind < 0)
            bail(errno, "read error on %s (%s)", g.inf, strerror(errno));

        g.name = (g.headis & 1) ? basename_of(g.inf) : NULL;
        g.mtime = (g.headis & 2) ? st.st_mtime : 0;
    }

    /* read the header if decoding */
    free(g.hname);
    g.hname = NULL;
    if (g.decode) {
        in_begin();
        method = read_header(1);
        if (method != 8 && method != 257 &&
            !(method == -2 && g.force && g.pipeout && g.decode != 2 &&
              !g.list)) {
            in_finish();
            if (method == -6)
                complain("skipping: %s corrupt: header crc error", g.inf);
            else if (method == -1)
                complain("skipping: %s empty", g.inf);
            else if (method < 0)
                complain("skipping: %s unrecognized format", g.inf);
            else
                complain("skipping: %s unknown compression method", g.inf);
            return;
        }

        if (g.decode == 2) {
            g.outd = -1;
            if (setjmp(pz_corrupt_jump) == 0) {
                if (method == 8)
                    inflate_check();
                else {
                    lzw_expand();
                    if (g.list) {
                        in_total -= 3;
                        show_info(method, 0, out_total, 0);
                    }
                }
            }
            else
                complain("skipping: %s", pz_corrupt_msg);
            in_finish();
            return;
        }
    }

    if (g.list) {
        list_info();
        in_finish();
        return;
    }

    /* set up the output */
    if (path == NULL || g.pipeout) {
        free(g.outf);
        g.outf = xstrdup("<stdout>");
        g.outd = 1;
        if (!g.decode && !g.force && isatty(1))
            bail(EINVAL, "trying to write compressed data to a terminal"
                 " (use -f to force)");
    }
    else {
        const char *to = g.inf, *sx = "";
        size_t pre = 0;

        if (g.decode) {
            if ((g.headis & 1) != 0 && g.hname != NULL) {
                pre = (size_t)(basename_of(g.inf) - g.inf);
                to = basename_of(g.hname);
                len = strlen(to);
            }
            else if (strcmp(to + len, ".tgz") == 0)
                sx = ".tar";
        }
        else
            sx = g.sufx;

        free(g.outf);
        g.outf = xmalloc(pre + len + strlen(sx) + 1);
        memcpy(g.outf, g.inf, pre);
        memcpy(g.outf + pre, to, len);
        strcpy(g.outf + pre + len, sx);
        g.outd = open(g.outf, O_CREAT | O_TRUNC | O_WRONLY |
                      (g.force ? 0 : O_EXCL), 0600);

        if (g.outd < 0 && errno == EEXIST && isatty(0) && g.verbosity) {
            int ch, reply = -1;
            fprintf(stderr, "%s exists -- overwrite (y/n)? ", g.outf);
            fflush(stderr);
            do {
                ch = getchar();
                if (reply < 0 && ch != ' ' && ch != '\t')
                    reply = ch == 'y' || ch == 'Y' ? 1 : 0;
            } while (ch != EOF && ch != '\n' && ch != '\r');
            if (reply == 1)
                g.outd = open(g.outf, O_CREAT | O_TRUNC | O_WRONLY, 0600);
        }

        if (g.outd < 0 && errno == EEXIST) {
            complain("skipping: %s exists", g.outf);
            free(g.outf);
            g.outf = NULL;
            in_finish();
            if (g.ind != 0)
                close(g.ind);
            return;
        }
        if (g.outd < 0) {
            int err = errno;
            bail(err, "write error on %s (%s)", g.outf, strerror(err));
        }
    }

    if (g.verbosity > 1) {
        fprintf(stderr, "%s to %s ", g.inf, g.outf);
        fflush(stderr);
    }
    if (g.decode) {
        if (setjmp(pz_corrupt_jump) == 0) {
            if (method == 8)
                inflate_check();
            else if (method == 257)
                lzw_expand();
            else
                copy_through();
        }
        else {
            complain("skipping: %s", pz_corrupt_msg);
            if (g.outd != -1 && g.outd != 1) {
                close(g.outd);
                g.outd = -1;
                unlink(g.outf);
                free(g.outf);
                g.outf = NULL;
            }
        }
    }
    else if (g.procs > 1)
        compress_parallel();
    else
        compress_single();
    if (g.verbosity > 1) {
        putc('\n', stderr);
        fflush(stderr);
    }

    in_finish();
    if (g.ind != 0) {
        close(g.ind);
    }
    if (g.outd != -1 && g.outd != 1) {
        if (g.sync)
            fsync(g.outd);
        if (close(g.outd)) {
            g.outd = -1;
            bail(errno, "write error on %s (%s)", g.outf, strerror(errno));
        }
        g.outd = -1;
        if (g.ind != 0) {
            copy_meta(g.inf, g.outf);
            if (!g.keep) {
                if (st.st_nlink > 1 && !g.force)
                    complain("%s has hard links -- not unlinking", g.inf);
                else
                    unlink(g.inf);
            }
        }
        if (g.decode && (g.headis & 2) != 0 && g.stamp)
            set_times(g.outf, g.stamp);
    }
    g.outd = -1;
    free(g.outf);
    g.outf = NULL;
}

/* ---- main ------------------------------------------------------------- */

int main(int argc, char **argv)
{
    int n, nop, done;
    char **args;
    long ncpu;
    size_t plen;

    memset(&g, 0, sizeof(g));
    g.prog = basename_of(argv[0]);
    g.level = Z_DEFAULT_COMPRESSION == -1 ? 6 : 6;
    g.strategy = Z_DEFAULT_STRATEGY;
    g.sufx = ".gz";
    g.headis = 3;
    g.verbosity = 1;
    ncpu = sysconf(_SC_NPROCESSORS_ONLN);
    g.procs = ncpu < 1 ? 8 : (int)ncpu;
    g.block = 131072UL;
    g.setdict = 1;
    g.alias = "-";
    g.outd = -1;
    g.first = 1;
    zop_default_options(&g.zopts);
    signal(SIGPIPE, SIG_IGN);

    env_options("GZIP");
    env_options("PIGZ");

    if (strcmp(g.prog, "unpigz") == 0 || strcmp(g.prog, "gunzip") == 0) {
        if (!g.decode)
            g.headis >>= 2;
        g.decode = 1;
    }
    plen = strlen(g.prog);
    if (plen > 2 && strcmp(g.prog + plen - 3, "cat") == 0) {
        if (!g.decode)
            g.headis >>= 2;
        g.decode = 1;
        g.pipeout = 1;
    }

    if (argc < 2 && isatty(g.decode ? 0 : 1))
        show_help();

    args = xmalloc(sizeof(char *) * (size_t)(argc + 1));
    for (n = 0; n < argc; n++)
        args[n] = argv[n];
    args[argc] = NULL;

    nop = argc;
    for (n = 1; n < argc; n++) {
        if (strcmp(args[n], "--") == 0) {
            nop = n;
            args[n] = NULL;
            break;
        }
        else if (option(args[n]) == 0)
            args[n] = NULL;
    }
    option(NULL);

    done = 0;
    for (n = 1; n < argc; n++)
        if (args[n] != NULL) {
            if (done == 1 && g.pipeout && !g.decode && !g.list && g.form > 1)
                complain("warning: output will be concatenated zip files"
                         " -- %s will not be able to extract", g.prog);
            process(n < nop && strcmp(args[n], "-") == 0 ? NULL : args[n]);
            done++;
        }
    if (done == 0)
        process(NULL);

    fflush(stdout);
    return g.ret;
}
EOF"}

actions.command:
cd /workspace/src && cat > main.c <<'EOF'
/* main.c -- command line handling and per-file processing */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <errno.h>
#include <limits.h>
#include <unistd.h>
#include <fcntl.h>
#include <dirent.h>
#include <setjmp.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <zlib.h>
#include "pz.h"

struct settings g;

/* ---- messages ---------------------------------------------------------- */

void complain(const char *fmt, ...)
{
    va_list ap;
    if (g.verbosity > 0) {
        fprintf(stderr, "%s: ", g.prog);
        va_start(ap, fmt);
        vfprintf(stderr, fmt, ap);
        va_end(ap);
        putc('\n', stderr);
        fflush(stderr);
    }
    g.ret = 1;
}

/* remove a partially written output file */
static void drop_output(void)
{
    if (g.outd != -1 && g.outd != 1) {
        close(g.outd);
        g.outd = -1;
        if (g.outf != NULL)
            unlink(g.outf);
    }
}

void bail(int code, const char *fmt, ...)
{
    va_list ap;
    if (g.verbosity > 0) {
        fprintf(stderr, "%s: abort: ", g.prog);
        va_start(ap, fmt);
        vfprintf(stderr, fmt, ap);
        va_end(ap);
        putc('\n', stderr);
        fflush(stderr);
    }
    drop_output();
    fflush(stdout);
    _exit(code);
}

void *xmalloc(size_t n)
{
    void *p = malloc(n ? n : 1);
    if (p == NULL)
        bail(ENOMEM, "not enough memory");
    return p;
}

void *xrealloc(void *p, size_t n)
{
    p = realloc(p, n ? n : 1);
    if (p == NULL)
        bail(ENOMEM, "not enough memory");
    return p;
}

char *xstrdup(const char *s)
{
    size_t n = strlen(s) + 1;
    char *d = xmalloc(n);
    memcpy(d, s, n);
    return d;
}

/* ---- raw i/o ----------------------------------------------------------- */

void out_write(int fd, const void *buf, size_t len)
{
    const unsigned char *p = buf;
    while (len) {
        size_t chunk = len > 1U << 30 ? 1U << 30 : len;
        ssize_t n = write(fd, p, chunk);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            bail(errno, "write error on %s (%s)",
                 g.outf == NULL ? "<stdout>" : g.outf, strerror(errno));
        }
        p += n;
        len -= (size_t)n;
    }
}

size_t in_read(int fd, void *buf, size_t len)
{
    unsigned char *p = buf;
    size_t got = 0;
    while (len) {
        size_t chunk = len > 1U << 30 ? 1U << 30 : len;
        ssize_t n = read(fd, p, chunk);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            bail(errno, "read error on %s (%s)", g.inf, strerror(errno));
        }
        if (n == 0)
            break;
        p += n;
        got += (size_t)n;
        len -= (size_t)n;
    }
    return got;
}

/* ---- help and version ------------------------------------------------- */

static const char *helptext[] = {
"Usage: pigz [options] [files ...]",
"  will compress files in place, adding the suffix '.gz'. If no files are",
"  specified, stdin will be compressed to stdout. pigz does what gzip does,",
"  but spreads the work over multiple processors and cores when compressing.",
"",
"Options:",
"  -0 to -9, -11        Compression level (level 11, zopfli, is much slower)",
"  --fast, --best       Compression levels 1 and 9 respectively",
"  -A, --alias xxx      Use xxx as the name for any --zip entry from stdin",
"  -b, --blocksize mmm  Set compression block size to mmmK (default 128K)",
"  -c, --stdout         Write all processed output to stdout (won't delete)",
"  -C, --comment ccc    Put comment ccc in the gzip or zip header",
"  -d, --decompress     Decompress the compressed input",
"  -f, --force          Force overwrite, compress .gz, links, and to terminal",
"  -F  --first          Do iterations first, before block split for -11",
"  -h, --help           Display a help screen and quit",
"  -H, --huffman        Use only Huffman coding for compression",
"  -i, --independent    Compress blocks independently for damage recovery",
"  -I, --iterations n   Number of iterations for -11 optimization",
"  -J, --maxsplits n    Maximum number of split blocks for -11",
"  -k, --keep           Do not delete original file after processing",
"  -K, --zip            Compress to PKWare zip (.zip) single entry format",
"  -l, --list           List the contents of the compressed input",
"  -L, --license        Display the pigz license and quit",
"  -m, --no-time        Do not store or restore mod time",
"  -M, --time           Store or restore mod time",
"  -n, --no-name        Do not store or restore file name or mod time",
"  -N, --name           Store or restore file name and mod time",
"  -O  --oneblock       Do not split into smaller blocks for -11",
"  -p, --processes n    Allow up to n compression threads (default is the",
"                       number of online processors, or 8 if unknown)",
"  -q, --quiet          Print no messages, even on error",
"  -r, --recursive      Process the contents of all subdirectories",
"  -R, --rsyncable      Input-determined block locations for rsync",
"  -S, --suffix .sss    Use suffix .sss instead of .gz (for compression)",
"  -t, --test           Test the integrity of the compressed input",
"  -U, --rle            Use run-length encoding for compression",
"  -v, --verbose        Provide more verbose output",
"  -V  --version        Show the version of pigz",
"  -Y  --synchronous    Force output file write to permanent storage",
"  -z, --zlib           Compress to zlib (.zz) instead of gzip format",
"  --                   All arguments after \"--\" are treated as files",
NULL
};

static void show_help(void)
{
    int i;
    if (g.verbosity == 0)
        return;
    for (i = 0; helptext[i] != NULL; i++)
        fprintf(stderr, "%s\n", helptext[i]);
    fflush(stderr);
    exit(0);
}

/* ---- option parsing --------------------------------------------------- */

static const struct { const char *lng; char shrt; } longs[] = {
    {"LZW", 'Z'}, {"lzw", 'Z'}, {"alias", 'A'}, {"ascii", 'a'},
    {"best", '9'}, {"bits", 'Z'}, {"blocksize", 'b'}, {"decompress", 'd'},
    {"fast", '1'}, {"force", 'f'}, {"comment", 'C'}, {"first", 'F'},
    {"iterations", 'I'}, {"maxsplits", 'J'}, {"oneblock", 'O'},
    {"help", 'h'}, {"independent", 'i'}, {"keep", 'k'}, {"license", 'L'},
    {"list", 'l'}, {"name", 'N'}, {"no-name", 'n'}, {"no-time", 'm'},
    {"processes", 'p'}, {"quiet", 'q'}, {"recursive", 'r'},
    {"rsyncable", 'R'}, {"silent", 'q'}, {"stdout", 'c'}, {"suffix", 'S'},
    {"synchronous", 'Y'}, {"test", 't'}, {"time", 'M'}, {"to-stdout", 'c'},
    {"uncompress", 'd'}, {"verbose", 'v'}, {"version", 'V'}, {"zip", 'K'},
    {"zlib", 'z'}, {"huffman", 'H'}, {"rle", 'U'}, {NULL, 0}
};

/* parse a decimal number for an option parameter */
static size_t parse_num(const char *arg)
{
    const char *s = arg;
    size_t val = 0;
    if (*s == 0)
        bail(EINVAL, "internal error: empty parameter");
    do {
        unsigned d = (unsigned char)*s - '0';
        if (d > 9 || (val && (SIZE_MAX - d) / val < 10))
            bail(EINVAL, "invalid numeric parameter: %s", arg);
        val = val * 10 + d;
    } while (*++s);
    return val;
}

static int want;                /* option letter awaiting a parameter, or 0 */

static void take_param(const char *arg)
{
    size_t n;
    switch (want) {
    case 'b':
        n = parse_num(arg);
        g.block = n << 10;
        if (g.block < WINSZ)
            bail(EINVAL, "block size too small (must be >= 32K)");
        if (n != g.block >> 10 || g.block > (1UL << 29))
            bail(EINVAL, "block size too large: %s", arg);
        break;
    case 'p':
        n = parse_num(arg);
        g.procs = (int)n;
        if (g.procs < 1)
            bail(EINVAL, "invalid number of processes: %s", arg);
        if ((size_t)g.procs != n || g.procs > INT_MAX / 2 - 2)
            bail(EINVAL, "too many processes: %s", arg);
        break;
    case 'S':
        if (*arg == 0)
            bail(EINVAL, "suffix cannot be empty");
        g.sufx = arg;
        break;
    case 'I':
        g.zopts.numiterations = (int)parse_num(arg);
        break;
    case 'J':
        g.zopts.blocksplittingmax = (int)parse_num(arg);
        break;
    case 'A':
        g.alias = arg;
        break;
    case 'C':
        g.comment = arg;
        break;
    }
    want = 0;
}

/* process one argument (or NULL to check for a missing parameter) --
   return true if arg is a file name to process later */
static int option(const char *arg)
{
    if (want && (arg == NULL || *arg == '-'))
        bail(EINVAL, "missing parameter after -%c", want);
    if (arg == NULL)
        return 1;

    if (*arg == '-') {
        const char *p = arg + 1;
        char shortbuf[2];
        if (*p == 0)
            return 1;               /* "-" means stdin */
        if (*p == '-') {            /* long option */
            int j;
            for (j = 0; longs[j].lng != NULL; j++)
                if (strcmp(p + 1, longs[j].lng) == 0)
                    break;
            if (longs[j].lng == NULL)
                bail(EINVAL, "invalid option: %s", arg);
            shortbuf[0] = longs[j].shrt;
            shortbuf[1] = 0;
            p = shortbuf;
        }
        do {
            if (want) {
                if (want == 'S')
                    bail(EINVAL, "invalid usage: -S must be followed by space");
                break;              /* rest of argument is the parameter */
            }
            switch (*p) {
            case '0': case '1': case '2': case '3': case '4':
            case '5': case '6': case '7': case '8': case '9':
                g.level = *p - '0';
                while (p[1] >= '0' && p[1] <= '9') {
                    if (g.level && (INT_MAX - (p[1] - '0')) / g.level < 10)
                        bail(EINVAL, "only levels 0..9 and 11 are allowed");
                    g.level = g.level * 10 + *++p - '0';
                }
                if (g.level == 10 || g.level > 11)
                    bail(EINVAL, "only levels 0..9 and 11 are allowed");
                break;
            case 'A': case 'C': case 'I': case 'J': case 'S': case 'b':
            case 'p':
                want = *p;
                break;
            case 'F': g.zopts.blocksplittinglast = 1; break;
            case 'K': g.form = 2; g.sufx = ".zip"; break;
            case 'L':
                puts("pigz 2.8");
                puts("Copyright (C) 2007-2023 Mark Adler");
