            case 'N': g.headis = 0xf; break;
            case 'O': g.zopts.blocksplitting = 0; break;
            case 'R': g.rsync = 1; break;
            case 'V':
                puts("pigz 2.8");
                if (g.verbosity > 1)
                    printf("zlib %s\n", zlibVersion());
                exit(0);
            case 'Y': g.sync = 1; break;
            case 'Z':
                bail(EINVAL, "invalid option: LZW output not supported: -%c",
                     *p);
                break;
            case 'a':
                bail(EINVAL, "invalid option: no ascii conversion: -%c", *p);
                break;
            case 'c': g.pipeout = 1; break;
            case 'd':
                if (!g.decode)
                    g.headis >>= 2;
                g.decode = 1;
                break;
            case 'f': g.force = 1; break;
            case 'h': show_help(); break;
            case 'i': g.setdict = 0; break;
            case 'k': g.keep = 1; break;
            case 'l': g.list = 1; break;
            case 'n': g.headis = 0; break;
            case 'T':
            case 'm': g.headis &= ~0xa; break;
            case 'q': g.verbosity = 0; break;
            case 'r': g.recurse = 1; break;
            case 't': g.decode = 2; break;
            case 'U': g.strategy = Z_RLE; break;
            case 'H': g.strategy = Z_HUFFMAN_ONLY; break;
            case 'v': g.verbosity++; break;
            case 'z': g.form = 1; g.sufx = ".zz"; break;
            default:
                bail(EINVAL, "invalid option: -%c", *p);
            }
        } while (*++p);
        if (*p == 0)
            return 0;
        arg = p;
    }

    if (want) {
        take_param(arg);
        return 0;
    }
    return 1;
}

/* process options in an environment variable */
static void env_options(const char *var)
{
    char *val = getenv(var), *copy, *p, *q;
    if (val == NULL)
        return;
    copy = xstrdup(val);
    p = copy;
    while (*p) {
        while (*p == ' ' || *p == '\t')
            p++;
        q = p;
        while (*q && *q != ' ' && *q != '\t')
            q++;
        if (*q)
            *q++ = 0;
        if (option(p))
            bail(EINVAL, "cannot provide files in %s environment variable",
                 var);
        p = q;
    }
    option(NULL);
    /* copy is intentionally kept: parameters may point into it */
}

/* ---- file name helpers ------------------------------------------------ */

static const char *basename_of(const char *path)
{
    const char *p = strrchr(path, '/');
    return p == NULL ? path : p + 1;
}

/* length of a recognized compressed suffix at the end of nm, or 0 */
static size_t suffix_len(const char *nm)
{
    size_t len = strlen(nm);
    if (len > 4) {
        const char *s = nm + len - 4;
        if (!strcmp(s, ".zip") || !strcmp(s, ".ZIP") || !strcmp(s, ".tgz"))
            return 4;
    }
    if (len > 3) {
        const char *s = nm + len - 3;
        if (!strcmp(s, ".gz") || !strcmp(s, "-gz") || !strcmp(s, ".zz") ||
            !strcmp(s, "-zz"))
            return 3;
    }
    if (len > 2) {
        const char *s = nm + len - 2;
        if (!strcmp(s, ".z") || !strcmp(s, "-z") || !strcmp(s, "_z") ||
            !strcmp(s, ".Z"))
            return 2;
    }
    return 0;
}
size_t pz_suffix_len(const char *nm) { return suffix_len(nm); }

static void set_inf(const char *s, size_t at)
{
    size_t n = strlen(s);
    if (at + n + 1 > g.infsz) {
        g.infsz = at + n + 1 + 64;
        g.inf = xrealloc(g.inf, g.infsz);
    }
    memcpy(g.inf + at, s, n + 1);
}

/* copy permissions, owner, and times from one file to another */
static void copy_meta(const char *from, const char *to)
{
    struct stat st;
    struct timeval tv[2];
    if (stat(from, &st) != 0 || !S_ISREG(st.st_mode))
        return;
    (void)chmod(to, st.st_mode & 07777);
    (void)!chown(to, st.st_uid, st.st_gid);
    tv[0].tv_sec = st.st_atime;
    tv[0].tv_usec = 0;
    tv[1].tv_sec = st.st_mtime;
    tv[1].tv_usec = 0;
    (void)utimes(to, tv);
}

static void set_times(const char *path, time_t t)
{
    struct timeval tv[2];
    tv[0].tv_sec = t;
    tv[0].tv_usec = 0;
    tv[1].tv_sec = t;
    tv[1].tv_usec = 0;
    (void)utimes(path, tv);
}

/* ---- error recovery for corrupt input ---------------------------------- */

