            complain("skipping: %s is a directory", g.inf);
            return;
        }

        if (S_ISDIR(st.st_mode)) {
            DIR *dir;
            struct dirent *ent;
            char *names = NULL;
            size_t used = 0, room = 0, off, base;

            dir = opendir(g.inf);
            if (dir == NULL)
                return;
            while ((ent = readdir(dir)) != NULL) {
                const char *nm = ent->d_name;
                size_t n;
                if (nm[0] == 0 || (nm[0] == '.' && (nm[1] == 0 ||
                    (nm[1] == '.' && nm[2] == 0))))
                    continue;
                n = strlen(nm) + 1;
                if (used + n + 1 > room) {
                    room = (used + n + 1) * 2;
                    names = xrealloc(names, room);
                }
                memcpy(names + used, nm, n);
                used += n;
            }
            closedir(dir);
            if (names == NULL)
                return;
            names[used] = 0;

            if (len && g.inf[len - 1] != '/') {
                set_inf("/", len);
