            set_times(g.outf, g.stamp);
    }
    g.outd = -1;
    free(g.outf);
    g.outf = NULL;
}

/* ---- main ------------------------------------------------------------- */

int main(int argc, char **argv)
{
    int n, nop, done;
    char **args;
    long ncpu;
    size_t plen;

    memset(&g, 0, sizeof(g));
    g.prog = basename_of(argv[0]);
    g.level = Z_DEFAULT_COMPRESSION == -1 ? 6 : 6;
    g.strategy = Z_DEFAULT_STRATEGY;
    g.sufx = ".gz";
    g.headis = 3;
    g.verbosity = 1;
    ncpu = sysconf(_SC_NPROCESSORS_ONLN);
    g.procs = ncpu < 1 ? 8 : (int)ncpu;
    g.block = 131072UL;
    g.setdict = 1;
    g.alias = "-";
    g.outd = -1;
    g.first = 1;
    zop_default_options(&g.zopts);
    signal(SIGPIPE, SIG_IGN);

    env_options("GZIP");
    env_options("PIGZ");

    if (strcmp(g.prog, "unpigz") == 0 || strcmp(g.prog, "gunzip") == 0) {
        if (!g.decode)
            g.headis >>= 2;
        g.decode = 1;
    }
    plen = strlen(g.prog);
    if (plen > 2 && strcmp(g.prog + plen - 3, "cat") == 0) {
        if (!g.decode)
            g.headis >>= 2;
        g.decode = 1;
        g.pipeout = 1;
    }

    if (argc < 2 && isatty(g.decode ? 0 : 1))
        show_help();

    args = xmalloc(sizeof(char *) * (size_t)(argc + 1));
    for (n = 0; n < argc; n++)
        args[n] = argv[n];
    args[argc] = NULL;

    nop = argc;
    for (n = 1; n < argc; n++) {
        if (strcmp(args[n], "--") == 0) {
            nop = n;
            args[n] = NULL;
            break;
        }
        else if (option(args[n]) == 0)
            args[n] = NULL;
    }
    option(NULL);

    done = 0;
    for (n = 1; n < argc; n++)
        if (args[n] != NULL) {
            if (done == 1 && g.pipeout && !g.decode && !g.list && g.form > 1)
                complain("warning: output will be concatenated zip files"
                         " -- %s will not be able to extract", g.prog);
            process(n < nop && strcmp(args[n], "-") == 0 ? NULL : args[n]);
            done++;
        }
    if (done == 0)
        process(NULL);

    fflush(stdout);
    return g.ret;
}
