        put4(t + 12, zip64 ? LOW32 : (unsigned long)cent);
        put4(t + 16, zip64 ? LOW32 : (unsigned long)at);
        put2(t + 20, 0);
        out_write(g.outd, t, 22);
    }
    else if (g.form == 1) {
        t[0] = (unsigned char)(check >> 24);
        t[1] = (unsigned char)(check >> 16);
        t[2] = (unsigned char)(check >> 8);
        t[3] = (unsigned char)check;
        out_write(g.outd, t, 4);
    }
    else {
        put4(t, check);
        put4(t + 4, (unsigned long)(ulen & LOW32));
        out_write(g.outd, t, 8);
    }
}

static unsigned long check_update(unsigned long check,
                                  const unsigned char *buf, size_t len)
{
    while (len) {
        unsigned n = len > 0x40000000U ? 0x40000000U : (unsigned)len;
        check = g.form == 1 ? adler32(check, buf, n) : crc32(check, buf, n);
        buf += n;
        len -= n;
    }
    return check;
}

static unsigned long check_init(void)
{
    return g.form == 1 ? adler32(0L, Z_NULL, 0) : crc32(0L, Z_NULL, 0);
}

static void deflate_setup(z_stream *strm)
{
    int ret;
    memset(strm, 0, sizeof(*strm));
    ret = deflateInit2(strm, g.level, Z_DEFLATED, -15, 8, g.strategy);
    if (ret == Z_MEM_ERROR)
        bail(ENOMEM, "not enough memory");
    if (ret != Z_OK)
        bail(EINVAL, "internal error");
}

/* ---- single-threaded compression -------------------------------------- */

static uint64_t s_clen;
static unsigned char *s_out;
static unsigned s_outsz;

static void single_deflate(z_stream *strm, int flush)
{
    do {
        strm->avail_out = s_outsz;
        strm->next_out = s_out;
        (void)deflate(strm, flush);
        out_write(g.outd, s_out, s_outsz - strm->avail_out);
        s_clen += s_outsz - strm->avail_out;
    } while (strm->avail_out == 0);
}

static void zout(const void *buf, size_t len)
{
    out_write(g.outd, buf, len);
    s_clen += len;
}

void compress_single(void)
{
    size_t got, more, start, have, hist, left;
    int fresh;
    unsigned hash;
    unsigned char *in, *next, *scan, *nin;
    uint64_t head, ulen;
    unsigned long check;
    z_stream strm;
    size_t B = g.block;

    s_outsz = B > 0x80000000UL ? 0x80000000U : (unsigned)B;
    s_out = xmalloc(s_outsz);
    in = xmalloc(B + WINSZ);
    next = xmalloc(B + WINSZ);
    if (g.level <= 9)
        deflate_setup(&strm);
    s_clen = 0;

    head = write_header();

    got = 0;
    more = in_read(g.ind, next, B);
    ulen = more;
    start = 0;
    hist = 0;
    have = 0;
    check = check_init();
    hash = RSYNCHIT;
    nin = in;
    do {
        if (got == 0) {
            scan = in;
            in = next;
            next = scan;
            nin = in + start;
            got = more;
            if (g.level > 9) {
                left = start + more - hist;
                if (left > WINSZ)
                    left = WINSZ;
                memcpy(next, in + ((start + more) - left), left);
                start = left;
                hist = 0;
            }
            else
                start = 0;
            more = in_read(g.ind, next + start, B);
            ulen += more;
        }

        left = 0;
        if (g.rsync && got) {
            scan = nin;
            left = got;
            do {
                if (left == 0) {
                    if (more == 0 || got == B)
                        break;
                    if (g.level > 9) {
                        left = (size_t)(nin - in) - hist;
                        if (left > WINSZ)
                            left = WINSZ;
                    }
                    memmove(in, nin - left, left + got);
                    hist = 0;
                    nin = in + left;
                    scan = in + left + got;
                    left = more > B - got ? B - got : more;
                    memcpy(scan, next + start, left);
                    got += left;
                    more -= left;
                    start += left;
                    if (more == 0) {
                        more = in_read(g.ind, next, B);
                        ulen += more;
                        start = 0;
                    }
                }
                left--;
                hash = ((hash << 1) ^ *scan++) & RSYNCMASK;
            } while (hash != RSYNCHIT);
            got -= left;
        }

        fresh = 0;
        if (!g.setdict) {
            have += got;
            if (have > B) {
                fresh = 1;
                have = got;
            }
        }

        if (g.level <= 9) {
            if (fresh)
                (void)deflateReset(&strm);
            strm.next_in = nin;
            strm.avail_in = (unsigned)got;
            check = check_update(check, nin, got);
            nin += got;
            got = left;
            if (more || got) {
                int bits;
                single_deflate(&strm, Z_BLOCK);
                (void)deflatePending(&strm, Z_NULL, &bits);
                if ((bits & 1) || !g.setdict)
                    single_deflate(&strm, Z_SYNC_FLUSH);
                else if (bits & 7) {
                    do {
                        (void)deflatePrime(&strm, 10, 2);
                        (void)deflatePending(&strm, Z_NULL, &bits);
                    } while (bits & 7);
                    single_deflate(&strm, Z_BLOCK);
                }
                if (!g.setdict)
                    single_deflate(&strm, Z_FULL_FLUSH);
            }
            else
                single_deflate(&strm, Z_FINISH);
        }
        else {
            unsigned char bits = 0, *def = NULL;
            size_t size = 0, off;

            off = (size_t)(nin - in);
            if (fresh)
                hist = off;
            zop_deflate_part(&g.zopts, 2, !(more || left), in + hist,
                             off - hist, (off - hist) + got, &bits, &def,
                             &size);
            bits &= 7;
            if (more || left) {
                if ((bits & 1) || !g.setdict) {
                    zout(def, size);
                    if (bits == 0 || bits > 5)
                        zout("\0", 1);
                    zout("\0\0\xff\xff", 4);
                }
                else {
                    zout(def, size - 1);
                    if (bits)
                        do {
                            def[size - 1] += 2 << bits;
                            zout(def + size - 1, 1);
                            def[size - 1] = 0;
                            bits += 2;
                        } while (bits < 8);
                    zout(def + size - 1, 1);
                }
                if (!g.setdict)
                    zout("\0\0\0\xff\xff", 5);
            }
            else
                zout(def, size);
            free(def);
            check = check_update(check, nin, got);
            nin += got;
            got = left;
        }
    } while (more || got);

    if (g.level <= 9)
        deflateEnd(&strm);
    write_trailer(ulen, s_clen, check, head);
    free(in);
    free(next);
    free(s_out);
}

/* ---- parallel compression -------------------------------------------- */

struct buf {
    unsigned char *data;
    size_t len, size;
    int refs;
};

struct job {
    long seq;
    struct buf *in;             /* input to compress */
    struct buf *dict;           /* dictionary source, or NULL */
    size_t *lens;               /* sub-block lengths (rsync), or NULL */
    size_t nlens;
    int more;                   /* true if more input follows this job */
    unsigned char *out;         /* compressed output */
    size_t outlen, outsize;
    int done;
    struct job *qnext;          /* work queue link */
};

static pthread_mutex_t q_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t q_cond = PTHREAD_COND_INITIALIZER;
static pthread_cond_t d_cond = PTHREAD_COND_INITIALIZER;
static struct job *q_head, *q_tail;
static int q_quit;

static struct buf *buf_new(size_t size)
{
    struct buf *b = xmalloc(sizeof(struct buf));
    b->data = xmalloc(size);
    b->len = 0;
    b->size = size;
    b->refs = 1;
    return b;
}

static void buf_drop(struct buf *b)
{
    int last;
    if (b == NULL)
        return;
    pthread_mutex_lock(&q_lock);
    last = --b->refs == 0;
    pthread_mutex_unlock(&q_lock);
    if (last) {
        free(b->data);
        free(b);
    }
}

static void out_room(struct job *job, size_t need)
{
    if (job->outsize - job->outlen < need) {
        job->outsize = job->outlen + need + (job->outsize >> 1);
        job->out = xrealloc(job->out, job->outsize);
    }
}

static void job_deflate(z_stream *strm, struct job *job, int flush)
{
    do {
        size_t room = job->outsize - job->outlen;
        if (room == 0) {
            out_room(job, 65536);
            room = job->outsize - job->outlen;
        }
        strm->next_out = job->out + job->outlen;
        strm->avail_out = room < UINT32_MAX ? (unsigned)room : UINT32_MAX;
        (void)deflate(strm, flush);
        job->outlen = (size_t)(strm->next_out - job->out);
    } while (strm->avail_out == 0);
}

static void job_compress(struct job *job)
{
    size_t left = job->in->len, i = 0, len;
    size_t B = g.block;
    z_stream strm;
    unsigned char *temp = NULL;
    size_t tlen = 0;

    job->outsize = B + (B >> 4) + WINSZ;
    if (job->outsize < job->in->len + (job->in->len >> 4) + WINSZ)
        job->outsize = job->in->len + (job->in->len >> 4) + WINSZ;
    job->out = xmalloc(job->outsize);
    job->outlen = 0;

    if (g.level <= 9) {
        deflate_setup(&strm);
        if (job->dict != NULL) {
            size_t dl = job->dict->len, use = dl < WINSZ ? dl : WINSZ;
            deflateSetDictionary(&strm, job->dict->data + (dl - use),
                                 (unsigned)use);
        }
        strm.next_in = job->in->data;
    }
    else {
        size_t use = 0;
        if (job->dict != NULL) {
            size_t dl = job->dict->len;
            use = dl < WINSZ ? dl : WINSZ;
        }
        temp = xmalloc(use + job->in->len + 1);
        if (use)
            memcpy(temp, job->dict->data + (job->dict->len - use), use);
        memcpy(temp + use, job->in->data, job->in->len);
        tlen = use;
    }
    buf_drop(job->dict);
    job->dict = NULL;

    do {
        len = job->lens == NULL || i >= job->nlens ? left : job->lens[i++];
        if (len > left)
            len = left;
        left -= len;
        if (g.level <= 9) {
            strm.avail_in = (unsigned)len;
            if (left || job->more) {
                int bits;
                job_deflate(&strm, job, Z_BLOCK);
                (void)deflatePending(&strm, Z_NULL, &bits);
                if ((bits & 1) || !g.setdict)
                    job_deflate(&strm, job, Z_SYNC_FLUSH);
                else if (bits & 7) {
                    do {
                        (void)deflatePrime(&strm, 10, 2);
                        (void)deflatePending(&strm, Z_NULL, &bits);
                    } while (bits & 7);
                    job_deflate(&strm, job, Z_BLOCK);
                }
                if (!g.setdict)
                    job_deflate(&strm, job, Z_FULL_FLUSH);
            }
            else
                job_deflate(&strm, job, Z_FINISH);
        }
        else {
            unsigned char bits = 0, *out = NULL;
            size_t outsize = 0;
            zop_deflate_part(&g.zopts, 2, !(left || job->more), temp, tlen,
                             tlen + len, &bits, &out, &outsize);
            out_room(job, outsize + 16);
            memcpy(job->out + job->outlen, out, outsize);
            free(out);
            job->outlen += outsize;
            if (left || job->more) {
                bits &= 7;
                if ((bits & 1) || !g.setdict) {
                    if (bits == 0 || bits > 5)
                        job->out[job->outlen++] = 0;
                    job->out[job->outlen++] = 0;
                    job->out[job->outlen++] = 0;
                    job->out[job->outlen++] = 0xff;
                    job->out[job->outlen++] = 0xff;
                }
                else if (bits) {
                    do {
                        job->out[job->outlen - 1] += 2 << bits;
                        job->out[job->outlen++] = 0;
                        bits += 2;
                    } while (bits < 8);
                }
                if (!g.setdict) {
                    job->out[job->outlen++] = 0;
                    job->out[job->outlen++] = 0;
                    job->out[job->outlen++] = 0;
                    job->out[job->outlen++] = 0xff;
                    job->out[job->outlen++] = 0xff;
                }
            }
            tlen += len;
        }
    } while (left);

    if (g.level <= 9)
        deflateEnd(&strm);
    free(temp);
}

static void *worker(void *arg)
{
    (void)arg;
    for (;;) {
        struct job *job;
        pthread_mutex_lock(&q_lock);
        while (q_head == NULL && !q_quit)
            pthread_cond_wait(&q_cond, &q_lock);
        if (q_head == NULL) {
            pthread_mutex_unlock(&q_lock);
            return NULL;
        }
        job = q_head;
        q_head = job->qnext;
        if (q_head == NULL)
            q_tail = NULL;
        pthread_mutex_unlock(&q_lock);

        job_compress(job);

        pthread_mutex_lock(&q_lock);
        job->done = 1;
        pthread_cond_broadcast(&d_cond);
        pthread_mutex_unlock(&q_lock);
    }
}

/* pending jobs in order */
static struct job **pend;
static size_t pend_head, pend_count, pend_cap;
static pthread_t *threads;
static int nthreads, maxthreads;
static uint64_t p_clen;

static void write_oldest(void)
{
    struct job *job = pend[pend_head];
    pthread_mutex_lock(&q_lock);
    while (!job->done)
        pthread_cond_wait(&d_cond, &q_lock);
    pthread_mutex_unlock(&q_lock);
    out_write(g.outd, job->out, job->outlen);
    p_clen += job->outlen;
    free(job->out);
    buf_drop(job->in);
    free(job->lens);
    free(job);
    pend_head = (pend_head + 1) % pend_cap;
    pend_count--;
}

static void submit(struct job *job)
{
    if (nthreads < maxthreads && nthreads < (int)job->seq + 1) {
        pthread_create(&threads[nthreads], NULL, worker, NULL);
        nthreads++;
    }
    while (pend_count == pend_cap)
        write_oldest();
    pend[(pend_head + pend_count) % pend_cap] = job;
    pend_count++;
    pthread_mutex_lock(&q_lock);
    job->qnext = NULL;
    if (q_tail == NULL)
        q_head = job;
    else
        q_tail->qnext = job;
    q_tail = job;
    pthread_cond_signal(&q_cond);
    pthread_mutex_unlock(&q_lock);
}

static void add_len(struct job *job, size_t len)
{
    job->lens = xrealloc(job->lens, sizeof(size_t) * (job->nlens + 1));
    job->lens[job->nlens++] = len;
}

void compress_parallel(void)
{
    long seq = 0;
    struct buf *curr, *next, *hold, *dict;
    int more;
    unsigned hash;
    unsigned char *scan, *end, *last;
    size_t left, len;
    unsigned long check;
    uint64_t head, ulen = 0;
    size_t B = g.block;
    size_t limit;
    int i;

    /* bound memory in flight */
    limit = (size_t)g.procs + 2;
    if (limit > 64)
        limit = 64;
    if (limit * B > (size_t)3 << 30)
        limit = ((size_t)3 << 30) / B;
    if (limit < 2)
        limit = 2;
    maxthreads = g.procs < (int)limit ? g.procs : (int)limit;
    threads = xmalloc(sizeof(pthread_t) * (size_t)maxthreads);
    nthreads = 0;
    pend_cap = limit;
    pend = xmalloc(sizeof(struct job *) * pend_cap);
    pend_head = pend_count = 0;
    q_head = q_tail = NULL;
    q_quit = 0;
    p_clen = 0;

    head = write_header();
    check = check_init();

    next = buf_new(B);
    next->len = in_read(g.ind, next->data, B);
    hold = NULL;
    dict = NULL;
    scan = next->data;
    hash = RSYNCHIT;
    left = 0;
    do {
        struct job *job = xmalloc(sizeof(struct job));
        memset(job, 0, sizeof(*job));

        curr = next;
        next = hold;
        hold = NULL;
        if (next == NULL) {
            next = buf_new(B);
            next->len = in_read(g.ind, next->data, B);
        }

        if (g.rsync && curr->len) {
            int hits_only_term;
            if (left == 0) {
                last = curr->data;
                end = curr->data + curr->len;
                while (scan < end) {
                    hash = ((hash << 1) ^ *scan++) & RSYNCMASK;
                    if (hash == RSYNCHIT) {
                        add_len(job, (size_t)(scan - last));
                        last = scan;
                    }
                }
                left = (size_t)(scan - last);
                scan = next->data;
            }
            last = next->data;
            len = curr->size - curr->len;
            if (len > next->len)
                len = next->len;
            end = next->data + len;
            while (scan < end) {
                hash = ((hash << 1) ^ *scan++) & RSYNCMASK;
                if (hash == RSYNCHIT) {
                    add_len(job, (size_t)(scan - last) + left);
                    left = 0;
                    last = scan;
                }
            }
            hits_only_term = job->nlens == 0;

            len = (size_t)((hits_only_term ? scan : last) - next->data);
            if (len) {
                memcpy(curr->data + curr->len, next->data, len);
                curr->len += len;
                memmove(next->data, next->data + len, next->len - len);
                next->len -= len;
                scan -= len;
                left = 0;
            }
            else if (!hits_only_term && left && next->len) {
                hold = next;
                next = buf_new(B);
                memcpy(next->data, curr->data + (curr->len - left), left);
                next->len = left;
                curr->len -= left;
            }
            else
                left = 0;
        }

        job->in = curr;
        ulen += curr->len;
        check = check_update(check, curr->data, curr->len);

        more = next->len != 0;
        job->more = more;

        job->dict = dict;
        dict = NULL;
        if (more && g.setdict) {
            if (curr->len >= WINSZ || job->dict == NULL) {
                dict = curr;
                pthread_mutex_lock(&q_lock);
                curr->refs++;
                pthread_mutex_unlock(&q_lock);
            }
            else {
                size_t need = WINSZ - curr->len, have = job->dict->len;
                dict = buf_new(WINSZ);
                if (need > have)
                    need = have;
                memcpy(dict->data, job->dict->data + (have - need), need);
                memcpy(dict->data + need, curr->data, curr->len);
                dict->len = need + curr->len;
            }
        }
        if (job->dict != NULL) {
            pthread_mutex_lock(&q_lock);
            pthread_mutex_unlock(&q_lock);
        }

        job->seq = seq++;
        submit(job);
    } while (more);
    buf_drop(next);
    buf_drop(hold);
    buf_drop(dict);

    while (pend_count)
        write_oldest();

    pthread_mutex_lock(&q_lock);
    q_quit = 1;
    pthread_cond_broadcast(&q_cond);
    pthread_mutex_unlock(&q_lock);
    for (i = 0; i < nthreads; i++)
        pthread_join(threads[i], NULL);
    free(threads);
    free(pend);

    write_trailer(ulen, p_clen, check, head);
}
EOF"}

