cd /workspace/src && cat > compress.c <<'EOF'
/* compress.c -- gzip/zlib/zip wrappers and block compression */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>
#include <zlib.h>
#include "pz.h"

#define RSYNCBITS 12
#define RSYNCMASK ((1U << RSYNCBITS) - 1)
#define RSYNCHIT (RSYNCMASK >> 1)
#define LOW32 0xffffffffUL

static void put2(unsigned char *p, unsigned long v)
{
    p[0] = (unsigned char)v;
    p[1] = (unsigned char)(v >> 8);
}

static void put4(unsigned char *p, unsigned long v)
{
    put2(p, v & 0xffff);
    put2(p + 2, (v >> 16) & 0xffff);
}

static void put8(unsigned char *p, uint64_t v)
{
    put4(p, (unsigned long)(v & LOW32));
    put4(p + 4, (unsigned long)(v >> 32));
}

/* convert a Unix time to MS-DOS date and time */
static unsigned long dos_time(time_t t)
{
    struct tm *tm;
    unsigned long dos;
    if (t == 0)
        t = time(NULL);
    tm = localtime(&t);
    if (tm == NULL || tm->tm_year < 80 || tm->tm_year > 207)
        return 0;
    dos = (unsigned long)(tm->tm_year - 80) << 25;
    dos += (unsigned long)(tm->tm_mon + 1) << 21;
    dos += (unsigned long)tm->tm_mday << 16;
    dos += (unsigned long)tm->tm_hour << 11;
    dos += (unsigned long)tm->tm_min << 5;
    dos += (unsigned long)(tm->tm_sec + 1) >> 1;
    return dos;
}

/* write the header for the selected format, return its length */
static uint64_t write_header(void)
{
    unsigned char h[30];
    uint64_t len;

    if (g.form > 1) {
        const char *nm = g.name == NULL ? g.alias : g.name;
        size_t n = strlen(nm);
        put4(h, 0x04034b50UL);
        put2(h + 4, 45);
        put2(h + 6, 8);
        put2(h + 8, 8);
        put4(h + 10, dos_time(g.mtime));
        put4(h + 14, 0);
        put4(h + 18, LOW32);
        put4(h + 22, LOW32);
        put2(h + 26, n);
        put2(h + 28, 29);
        out_write(g.outd, h, 30);
        out_write(g.outd, nm, n);
        len = 30 + n;
        put2(h, 0x0001);
        put2(h + 2, 16);
        put8(h + 4, 0);
        put8(h + 12, 0);
        put2(h + 20, 0x5455);
        put2(h + 22, 5);
        h[24] = 1;
        put4(h + 25, (unsigned long)g.mtime);
        out_write(g.outd, h, 29);
        len += 29;
    }
    else if (g.form == 1) {
        unsigned head = 0x7800;
        head |= (g.level >= 9 ? 3 : g.level == 1 ? 0 : g.level >= 6 ? 1 : 2)
                << 6;
        head += 31 - (head % 31);
        h[0] = (unsigned char)(head >> 8);
        h[1] = (unsigned char)head;
        out_write(g.outd, h, 2);
        len = 2;
    }
    else {
        h[0] = 31;
        h[1] = 139;
        h[2] = 8;
        h[3] = (g.name != NULL ? 8 : 0) + (g.comment != NULL ? 16 : 0);
        put4(h + 4, (unsigned long)g.mtime);
        h[8] = g.level >= 9 ? 2 : (g.level == 1 ? 4 : 0);
        h[9] = 3;
        out_write(g.outd, h, 10);
        len = 10;
        if (g.name != NULL) {
            out_write(g.outd, g.name, strlen(g.name) + 1);
            len += strlen(g.name) + 1;
        }
        if (g.comment != NULL) {
