        check = g.form == 1 ? adler32(check, buf, n) : crc32(check, buf, n);
        buf += n;
        len -= n;
    }
    return check;
}

static unsigned long check_init(void)
{
    return g.form == 1 ? adler32(0L, Z_NULL, 0) : crc32(0L, Z_NULL, 0);
