    memset(strm, 0, sizeof(*strm));
    ret = deflateInit2(strm, g.level, Z_DEFLATED, -15, 8, g.strategy);
    if (ret == Z_MEM_ERROR)
        bail(ENOMEM, "not enough memory");
    if (ret != Z_OK)
        bail(EINVAL, "internal error");
