/* ---- single-threaded compression -------------------------------------- */

static uint64_t s_clen;
static unsigned char *s_out;
static unsigned s_outsz;

static void single_deflate(z_stream *strm, int flush)
{
    do {
        strm->avail_out = s_outsz;
        strm->next_out = s_out;
        (void)deflate(strm, flush);
        out_write(g.outd, s_out, s_outsz - strm->avail_out);
        s_clen += s_outsz - strm->avail_out;
    } while (strm->avail_out == 0);
}

static void zout(const void *buf, size_t len)
{
    out_write(g.outd, buf, len);
    s_clen += len;
}

void compress_single(void)
{
    size_t got, more, start, have, hist, left;
    int fresh;
    unsigned hash;
    unsigned char *in, *next, *scan, *nin;
