                    memmove(in, nin - left, left + got);
                    hist = 0;
                    nin = in + left;
                    scan = in + left + got;
                    left = more > B - got ? B - got : more;
                    memcpy(scan, next + start, left);
                    got += left;
                    more -= left;
                    start += left;
