                int bits;
                single_deflate(&strm, Z_BLOCK);
                (void)deflatePending(&strm, Z_NULL, &bits);
                if ((bits & 1) || !g.setdict)
                    single_deflate(&strm, Z_SYNC_FLUSH);
                else if (bits & 7) {
                    do {
