                        (void)deflatePending(&strm, Z_NULL, &bits);
                    } while (bits & 7);
                    single_deflate(&strm, Z_BLOCK);
                }
                if (!g.setdict)
                    single_deflate(&strm, Z_FULL_FLUSH);
            }
            else
                single_deflate(&strm, Z_FINISH);
        }
        else {
            unsigned char bits = 0, *def = NULL;
            size_t size = 0, off;

            off = (size_t)(nin - in);
            if (fresh)
                hist = off;
            zop_deflate_part(&g.zopts, 2, !(more || left), in + hist,
                             off - hist, (off - hist) + got, &bits, &def,
                             &size);
            bits &= 7;
            if (more || left) {
                if ((bits & 1) || !g.setdict) {
                    zout(def, size);
                    if (bits == 0 || bits > 5)
                        zout("\0", 1);
                    zout("\0\0\xff\xff", 4);
                }
                else {
                    zout(def, size - 1);
                    if (bits)
                        do {
                            def[size - 1] += 2 << bits;
                            zout(def + size - 1, 1);
                            def[size - 1] = 0;
                            bits += 2;
                        } while (bits < 8);
                    zout(def + size - 1, 1);
                }
                if (!g.setdict)
                    zout("\0\0\0\xff\xff", 5);
            }
            else
                zout(def, size);
            free(def);
            check = check_update(check, nin, got);
            nin += got;
            got = left;
        }
    } while (more || got);

    if (g.level <= 9)
        deflateEnd(&strm);
    write_trailer(ulen, s_clen, check, head);
    free(in);
    free(next);
    free(s_out);
}

/* ---- parallel compression -------------------------------------------- */

struct buf {
    unsigned char *data;
    size_t len, size;
    int refs;
};

struct job {
    long seq;
    struct buf *in;             /* input to compress */
    struct buf *dict;           /* dictionary source, or NULL */
    size_t *lens;               /* sub-block lengths (rsync), or NULL */
    size_t nlens;
    int more;                   /* true if more input follows this job */
    unsigned char *out;         /* compressed output */
    size_t outlen, outsize;
    int done;
    struct job *qnext;          /* work queue link */
};

static pthread_mutex_t q_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t q_cond = PTHREAD_COND_INITIALIZER;
static pthread_cond_t d_cond = PTHREAD_COND_INITIALIZER;
static struct job *q_head, *q_tail;
static int q_quit;

static struct buf *buf_new(size_t size)
{
    struct buf *b = xmalloc(sizeof(struct buf));
    b->data = xmalloc(size);
    b->len = 0;
    b->size = size;
    b->refs = 1;
    return b;
}

static void buf_drop(struct buf *b)
{
    int last;
    if (b == NULL)
        return;
    pthread_mutex_lock(&q_lock);
    last = --b->refs == 0;
    pthread_mutex_unlock(&q_lock);
    if (last) {
        free(b->data);
        free(b);
    }
}

static void out_room(struct job *job, size_t need)
{
    if (job->outsize - job->outlen < need) {
        job->outsize = job->outlen + need + (job->outsize >> 1);
        job->out = xrealloc(job->out, job->outsize);
    }
}

static void job_deflate(z_stream *strm, struct job *job, int flush)
{
    do {
        size_t room = job->outsize - job->outlen;
        if (room == 0) {
            out_room(job, 65536);
            room = job->outsize - job->outlen;
        }
        strm->next_out = job->out + job->outlen;
        strm->avail_out = room < UINT32_MAX ? (unsigned)room : UINT32_MAX;
        (void)deflate(strm, flush);
        job->outlen = (size_t)(strm->next_out - job->out);
    } while (strm->avail_out == 0);
}

static void job_compress(struct job *job)
{
    size_t left = job->in->len, i = 0, len;
    size_t B = g.block;
    z_stream strm;
    unsigned char *temp = NULL;
    size_t tlen = 0;

    job->outsize = B + (B >> 4) + WINSZ;
    if (job->outsize < job->in->len + (job->in->len >> 4) + WINSZ)
        job->outsize = job->in->len + (job->in->len >> 4) + WINSZ;
    job->out = xmalloc(job->outsize);
    job->outlen = 0;

    if (g.level <= 9) {
        deflate_setup(&strm);
        if (job->dict != NULL) {
            size_t dl = job->dict->len, use = dl < WINSZ ? dl : WINSZ;
            deflateSetDictionary(&strm, job->dict->data + (dl - use),
                                 (unsigned)use);
        }
        strm.next_in = job->in->data;
    }
    else {
        size_t use = 0;
        if (job->dict != NULL) {
            size_t dl = job->dict->len;
            use = dl < WINSZ ? dl : WINSZ;
        }
        temp = xmalloc(use + job->in->len + 1);
        if (use)
            memcpy(temp, job->dict->data + (job->dict->len - use), use);
        memcpy(temp + use, job->in->data, job->in->len);
        tlen = use;
    }
    buf_drop(job->dict);
    job->dict = NULL;

    do {
        len = job->lens == NULL || i >= job->nlens ? left : job->lens[i++];
        if (len > left)
            len = left;
        left -= len;
        if (g.level <= 9) {
            strm.avail_in = (unsigned)len;
            if (left || job->more) {
                int bits;
                job_deflate(&strm, job, Z_BLOCK);
                (void)deflatePending(&strm, Z_NULL, &bits);
                if ((bits & 1) || !g.setdict)
                    job_deflate(&strm, job, Z_SYNC_FLUSH);
                else if (bits & 7) {
                    do {
                        (void)deflatePrime(&strm, 10, 2);
                        (void)deflatePending(&strm, Z_NULL, &bits);
                    } while (bits & 7);
                    job_deflate(&strm, job, Z_BLOCK);
                }
                if (!g.setdict)
                    job_deflate(&strm, job, Z_FULL_FLUSH);
            }
            else
                job_deflate(&strm, job, Z_FINISH);
        }
        else {
            unsigned char bits = 0, *out = NULL;
            size_t outsize = 0;
            zop_deflate_part(&g.zopts, 2, !(left || job->more), temp, tlen,
                             tlen + len, &bits, &out, &outsize);
            out_room(job, outsize + 16);
            memcpy(job->out + job->outlen, out, outsize);
            free(out);
