                    job->out[job->outlen++] = 0;
                    job->out[job->outlen++] = 0;
                    job->out[job->outlen++] = 0xff;
                    job->out[job->outlen++] = 0xff;
                }
                else if (bits) {
                    do {
                        job->out[job->outlen - 1] += 2 << bits;
                        job->out[job->outlen++] = 0;
