    if (g.level <= 9)
        deflateEnd(&strm);
    free(temp);
}

static void *worker(void *arg)
{
    (void)arg;
    for (;;) {
        struct job *job;
        pthread_mutex_lock(&q_lock);
        while (q_head == NULL && !q_quit)
            pthread_cond_wait(&q_cond, &q_lock);
        if (q_head == NULL) {
            pthread_mutex_unlock(&q_lock);
            return NULL;
        }
        job = q_head;
        q_head = job->qnext;
        if (q_head == NULL)
            q_tail = NULL;
        pthread_mutex_unlock(&q_lock);

        job_compress(job);

        pthread_mutex_lock(&q_lock);
        job->done = 1;
        pthread_cond_broadcast(&d_cond);
        pthread_mutex_unlock(&q_lock);
    }
}

/* pending jobs in order */
static struct job **pend;
static size_t pend_head, pend_count, pend_cap;
static pthread_t *threads;
static int nthreads, maxthreads;
static uint64_t p_clen;

static void write_oldest(void)
{
    struct job *job = pend[pend_head];
    pthread_mutex_lock(&q_lock);
    while (!job->done)
        pthread_cond_wait(&d_cond, &q_lock);
    pthread_mutex_unlock(&q_lock);
    out_write(g.outd, job->out, job->outlen);
    p_clen += job->outlen;
    free(job->out);
    buf_drop(job->in);
    free(job->lens);
    free(job);
    pend_head = (pend_head + 1) % pend_cap;
    pend_count--;
}

static void submit(struct job *job)
{
    if (nthreads < maxthreads && nthreads < (int)job->seq + 1) {
        pthread_create(&threads[nthreads], NULL, worker, NULL);
        nthreads++;
    }
    while (pend_count == pend_cap)
        write_oldest();
    pend[(pend_head + pend_count) % pend_cap] = job;
    pend_count++;
    pthread_mutex_lock(&q_lock);
    job->qnext = NULL;
    if (q_tail == NULL)
        q_head = job;
    else
        q_tail->qnext = job;
    q_tail = job;
    pthread_cond_signal(&q_cond);
    pthread_mutex_unlock(&q_lock);
}

static void add_len(struct job *job, size_t len)
{
    job->lens = xrealloc(job->lens, sizeof(size_t) * (job->nlens + 1));
    job->lens[job->nlens++] = len;
}

void compress_parallel(void)
{
