    threads = xmalloc(sizeof(pthread_t) * (size_t)maxthreads);
    nthreads = 0;
    pend_cap = limit;
    pend = xmalloc(sizeof(struct job *) * pend_cap);
    pend_head = pend_count = 0;
    q_head = q_tail = NULL;
    q_quit = 0;
    p_clen = 0;

