            int hits_only_term;
            if (left == 0) {
                last = curr->data;
                end = curr->data + curr->len;
                while (scan < end) {
                    hash = ((hash << 1) ^ *scan++) & RSYNCMASK;
                    if (hash == RSYNCHIT) {
