            last = next->data;
            len = curr->size - curr->len;
            if (len > next->len)
                len = next->len;
            end = next->data + len;
            while (scan < end) {
                hash = ((hash << 1) ^ *scan++) & RSYNCMASK;
                if (hash == RSYNCHIT) {
