            pthread_mutex_lock(&q_lock);
            pthread_mutex_unlock(&q_lock);
        }

        job->seq = seq++;
        submit(job);
    } while (more);
    buf_drop(next);
    buf_drop(hold);
    buf_drop(dict);

    while (pend_count)
        write_oldest();

    pthread_mutex_lock(&q_lock);
    q_quit = 1;
    pthread_cond_broadcast(&q_cond);
    pthread_mutex_unlock(&q_lock);
    for (i = 0; i < nthreads; i++)
        pthread_join(threads[i], NULL);
    free(threads);
    free(pend);

    write_trailer(ulen, p_clen, check, head);
}
