static unsigned char *in_next;
static size_t in_left;
static int in_eof;
static int magic1;              /* first byte of the header, or -1 */
static unsigned long out_check;

/* signal corrupt input to process() */
static void corrupt(const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(pz_corrupt_msg, sizeof(pz_corrupt_msg), fmt, ap);
    va_end(ap);
    longjmp(pz_corrupt_jump, 1);
}

static size_t load(void)
{
    if (in_eof) {
        in_left = 0;
        return 0;
    }
    in_left = in_read(g.ind, ibuf, IBUFSZ);
    in_next = ibuf;
    in_total += (int64_t)in_left;
    if (in_left == 0)
        in_eof = 1;
    return in_left;
}

void in_begin(void)
{
    in_left = 0;
    in_next = ibuf;
    in_eof = 0;
    in_total = 0;
    magic1 = -1;
}

void in_finish(void)
{
}

static int64_t in_pos(void)
{
    return in_total - (int64_t)in_left;
}

/* header byte reading, optionally accumulating a crc */
static int hcrc_on;
static unsigned long hcrc;

static unsigned get1(void)
{
    unsigned char c;
    if (in_left == 0 && (in_eof || load() == 0))
        return 0;
    in_left--;
    c = *in_next++;
    if (hcrc_on)
        hcrc = crc32(hcrc, &c, 1);
    return c;
}

static unsigned get2(void)
{
    unsigned v = get1();
    return v + (get1() << 8);
}

static unsigned long get4(void)
{
    unsigned long v = get2();
    return v + ((unsigned long)get2() << 16);
}

static void skip(uint64_t n)
{
    if (hcrc_on) {
        while (n-- && !in_eof)
            get1();
        return;
    }
    while (n > in_left) {
        n -= in_left;
        in_left = 0;
        if (load() == 0)
            return;
    }
    in_left -= (size_t)n;
    in_next += n;
}

/* read a zero-terminated string; store it if save */
static char *get_string(int save)
{
    char *s = NULL;
    size_t len = 0, size = 0;
    for (;;) {
        unsigned c = get1();
        if (in_eof)
            break;
        if (save) {
            if (len + 1 >= size) {
                size = size ? size * 2 : 64;
                s = xrealloc(s, size);
            }
            s[len++] = (char)c;
        }
        if (c == 0)
            break;
    }
    if (save) {
        if (s == NULL)
            s = xmalloc(1);
        s[len] = 0;
    }
    return s;
}

static time_t dos2time(unsigned long dos)
{
    struct tm tm;
    if (dos == 0)
        return time(NULL);
    memset(&tm, 0, sizeof(tm));
    tm.tm_year = ((int)(dos >> 25) & 0x7f) + 80;
    tm.tm_mon = ((int)(dos >> 21) & 0xf) - 1;
    tm.tm_mday = (int)(dos >> 16) & 0x1f;
    tm.tm_hour = (int)(dos >> 11) & 0x1f;
    tm.tm_min = (int)(dos >> 5) & 0x3f;
    tm.tm_sec = (int)(dos << 1) & 0x3e;
    tm.tm_isdst = -1;
    return mktime(&tm);
}

/* process zip extra field blocks */
static void read_extra(unsigned len, int save)
{
    while (len >= 4) {
        unsigned id = get2(), size = get2();
        if (in_eof)
            return;
        len -= 4;
        if (size > len)
            break;
        len -= size;
        if (id == 0x0001) {
            if (g.zip_ulen == LOW32 && size >= 8) {
                g.zip_ulen = get4();
                g.zip_ulen += (uint64_t)get4() << 32;
                size -= 8;
            }
            if (g.zip_clen == LOW32 && size >= 8) {
                g.zip_clen = get4();
                g.zip_clen += (uint64_t)get4() << 32;
                size -= 8;
            }
        }
        if (save) {
            if ((id == 0x000d || id == 0x5855) && size >= 8) {
                skip(4);
                g.stamp = (time_t)get4();
                size -= 8;
            }
            if (id == 0x5455 && size >= 5) {
                size--;
                if (get1() & 1) {
                    g.stamp = (time_t)get4();
                    size -= 4;
                }
            }
        }
        skip(size);
    }
    skip(len);
}

/* read a gzip, zlib, zip, or lzw header -- return the compression method,
   or negative on error: -1 empty, -2 not compressed, -3 premature end,
   -4 bad header, -5 zip central directory, -6 header crc error */
int read_header(int save)
{
    unsigned magic, method, flags, n, xlen;
    unsigned long t;

    if (save) {
        g.stamp = 0;
        free(g.hname);
        g.hname = NULL;
        free(g.hcomm);
        g.hcomm = NULL;
    }
    hcrc_on = 0;

    magic1 = (int)get1();
    if (in_eof) {
        magic1 = -1;
        return -1;
    }
    magic = (unsigned)magic1 << 8;
    magic += get1();
    if (in_eof)
        return -2;
    if (magic % 31 == 0 && (magic & 0x8f20) == 0x0800) {
        g.form = 1;
        return 8;
    }
    if (magic == 0x1f9d) {
        g.form = -1;
        return 257;
    }
    if (magic == 0x504b) {
        magic = get2();
        if (in_eof)
            return -3;
        if (magic == 0x0201 || magic == 0x0806)
            return -5;
        if (magic != 0x0403)
            return -4;
        skip(2);
        flags = get2();
        method = get2();
        t = get4();
        if (save)
            g.stamp = dos2time(t);
        g.zip_crc = get4();
        g.zip_clen = get4();
        g.zip_ulen = get4();
        n = get2();
        xlen = get2();
        if (in_eof)
            return -3;
        if (save) {
            char *nm = xmalloc(n + 1);
            unsigned i;
            for (i = 0; i < n; i++)
                nm[i] = (char)get1();
            nm[n] = 0;
            g.hname = nm;
        }
        else
            skip(n);
        read_extra(xlen, save);
        g.form = 2 + ((flags & 8) >> 3);
        return in_eof ? -3 : (int)method;
    }
    if (magic != 0x1f8b) {
        in_left++;
        in_next--;
        return -2;
    }

    hcrc = crc32(0L, Z_NULL, 0);
    {
        unsigned char m[2] = {0x1f, 0x8b};
        hcrc = crc32(hcrc, m, 2);
    }
    hcrc_on = 1;
    method = get1();
    flags = get1();
    if (flags & 0xe0) {
        hcrc_on = 0;
        return -4;
    }
    t = get4();
    if (save)
        g.stamp = (time_t)t;
    skip(2);
    if (flags & 4) {
        xlen = get2();
        if (in_eof) {
            hcrc_on = 0;
            return -3;
        }
        skip(xlen);
    }
    if (flags & 8) {
        char *s = get_string(save);
        if (save)
            g.hname = s;
    }
    if (flags & 16) {
        char *s = get_string(save);
        if (save)
            g.hcomm = s;
    }
    hcrc_on = 0;
    if (flags & 2) {
        unsigned want = (unsigned)(hcrc & 0xffff);
        if (get2() != want)
            return in_eof ? -3 : -6;
    }
    if (in_eof)
        return -3;
    g.form = 0;
    return (int)method;
}

/* ---- output of decompressed data ------------------------------------ */

static void out_data(const unsigned char *buf, size_t len)
{
    if (len == 0)
        return;
    if (g.decode == 1)
        out_write(g.outd, buf, len);
    out_total += (int64_t)len;
    {
        size_t left = len;
        const unsigned char *p = buf;
        while (left) {
            unsigned n = left > 0x40000000U ? 0x40000000U : (unsigned)left;
            out_check = g.form == 1 ? adler32(out_check, p, n) :
                        crc32(out_check, p, n);
            p += n;
            left -= n;
        }
    }
}

/* copy the input to the output (for -cdf on uncompressed data) */
void copy_through(void)
{
    if (magic1 != -1) {
        unsigned char c = (unsigned char)magic1;
        out_write(g.outd, &c, 1);
        out_total++;
    }
    while (in_left || load()) {
        out_write(g.outd, in_next, in_left);
        out_total += (int64_t)in_left;
        in_left = 0;
    }
}

/* ---- inflate ---------------------------------------------------------- */

static void inflate_member(unsigned char *win)
{
    z_stream strm;
    size_t wfill = 0;
    int r;

    memset(&strm, 0, sizeof(strm));
    r = inflateInit2(&strm, -15);
    if (r == Z_MEM_ERROR)
        bail(ENOMEM, "not enough memory");
    if (r != Z_OK)
        bail(EINVAL, "internal error");
    for (;;) {
        size_t used;
        strm.next_in = in_next;
        strm.avail_in = (unsigned)in_left;
        strm.next_out = win + wfill;
        strm.avail_out = WSIZE - (unsigned)wfill;
        r = inflate(&strm, Z_NO_FLUSH);
        used = in_left - strm.avail_in;
        in_next += used;
        in_left -= used;
        wfill = WSIZE - strm.avail_out;
        if (r == Z_STREAM_END)
            break;
        if (r == Z_DATA_ERROR) {
            char msg[256];
            snprintf(msg, sizeof(msg), "%s",
                     strm.msg == NULL ? "unknown" : strm.msg);
            inflateEnd(&strm);
            corrupt("%s: corrupted -- invalid deflate data (%s)", g.inf, msg);
        }
        if (r == Z_MEM_ERROR)
            bail(ENOMEM, "not enough memory");
        if (r != Z_OK && r != Z_BUF_ERROR)
            bail(EINVAL, "internal error");
        if (strm.avail_in == 0) {
            if (load() == 0) {
                inflateEnd(&strm);
                corrupt("%s: corrupted -- incomplete deflate data", g.inf);
            }
            continue;
        }
        /* output window full and more to come */
        out_data(win, wfill);
        wfill = 0;
    }
    inflateEnd(&strm);
    out_data(win, wfill);
}

static int64_t tot_in, tot_out;
static unsigned long tot_check;

void inflate_check(void)
{
    int ret = 0, cont = 0, was, members = 0;
    unsigned long check, len;
    int64_t clen, start;
    unsigned char *win = xmalloc(WSIZE);

    tot_in = tot_out = 0;
    tot_check = crc32(0L, Z_NULL, 0);
    do {
        start = in_pos();
        out_total = 0;
        out_check = g.form == 1 ? adler32(0L, Z_NULL, 0) :
                    crc32(0L, Z_NULL, 0);
        inflate_member(win);
        clen = in_pos() - start;

        if (g.form > 1) {
            if (g.form == 3) {
                g.zip_crc = get4();
                g.zip_clen = get4();
                g.zip_ulen = get4();
                if (g.zip_crc == 0x08074b50UL &&
                    (g.zip_crc != out_check ||
                     g.zip_clen != (uint64_t)(clen & LOW32) ||
                     g.zip_ulen != (uint64_t)(out_total & LOW32))) {
                    g.zip_crc = (unsigned long)g.zip_clen;
                    g.zip_clen = g.zip_ulen;
                    g.zip_ulen = get4();
                }
                if (g.zip_ulen != (uint64_t)(out_total & LOW32)) {
                    g.zip_ulen = get4();
                    (void)get4();
                }
                if (in_eof)
                    corrupt("%s: corrupted entry -- missing trailer", g.inf);
            }
            if ((g.zip_clen & LOW32) != (uint64_t)(clen & LOW32) ||
                (g.zip_ulen & LOW32) != (uint64_t)(out_total & LOW32))
                corrupt("%s: corrupted entry -- length mismatch", g.inf);
            check = g.zip_crc;
            if (check != out_check)
                corrupt("%s: corrupted entry -- crc32 mismatch", g.inf);
        }
        else if (g.form == 1) {
            check = (unsigned long)get1() << 24;
            check += (unsigned long)get1() << 16;
            check += (unsigned long)get1() << 8;
            check += get1();
            if (in_eof)
                corrupt("%s: corrupted -- missing trailer", g.inf);
            if (check != out_check)
                corrupt("%s: corrupted -- adler32 mismatch", g.inf);
        }
        else {
            check = get4();
            len = get4();
            if (in_eof)
                corrupt("%s: corrupted -- missing trailer", g.inf);
            if (check != out_check)
                corrupt("%s: corrupted -- crc32 mismatch", g.inf);
            if (len != (unsigned long)(out_total & LOW32))
                corrupt("%s: corrupted -- length mismatch", g.inf);
        }

        members++;
        tot_in += clen;
        tot_out += out_total;
        tot_check = crc32_combine(tot_check, check, (z_off_t)out_total);
        if (g.list) {
            in_total = clen;
            show_info(8, check, out_total, cont);
            cont = 1;
        }

        was = g.form;
        if (was == 0)
            ret = read_header(0);
    } while (was == 0 && ret == 8);
    free(win);

    if (g.list && members > 1) {
        in_total = tot_in;
        show_info(-1, tot_check, tot_out, 2);
    }

    if (was == 0) {
        if (ret == -1)
            ;
        else if (ret == -2 && g.force && g.pipeout && g.decode != 2 &&
                 !g.list)
            copy_through();
        else if (g.form == 0 && g.verbosity > 1)
            complain("warning: %s: trailing junk was ignored", g.inf);
        else if (g.form == 0)
            ;
    }
    else if (was == 1) {
        if ((in_left || load()) && g.verbosity > 1)
            complain("warning: %s: trailing junk was ignored", g.inf);
    }
    else {
        unsigned char sig[4];
        int i;
        for (i = 0; i < 4; i++) {
            sig[i] = (unsigned char)get1();
            if (in_eof)
                break;
        }
        if (i == 4 && sig[0] == 'P' && sig[1] == 'K' && sig[2] == 3 &&
            sig[3] == 4)
            complain("warning: %s: entries after the first were ignored",
                     g.inf);
    }
}

/* ---- LZW (compress) decoding ------------------------------------------ */

void lzw_expand(void)
{
    unsigned bits, mask, left, code, max, flags, end, prev, final, stack;
    unsigned long buf;
    int64_t mark;
    size_t outcnt;
    static unsigned short prefix[65536];
    static unsigned char suffix[65536];
    static unsigned char match[65280 + 2];
    static unsigned char obuf[WSIZE];

    out_total = 0;
    out_check = crc32(0L, Z_NULL, 0);
#define NOMORE() (in_left == 0 && (in_eof || load() == 0))
#define NEXT() (in_left--, *in_next++)
    if (NOMORE())
        corrupt("%s: lzw premature end", g.inf);
    flags = NEXT();
    if (flags & 0x60)
        corrupt("%s: unknown lzw flags set", g.inf);
    max = flags & 0x1f;
    if (max < 9 || max > 16)
        corrupt("%s: lzw bits out of range", g.inf);
    if (max == 9)
        max = 10;
    flags &= 0x80;

    mark = in_pos();
    bits = 9;
    mask = 0x1ff;
    end = flags ? 256 : 255;

    if (NOMORE())
        return;
    buf = NEXT();
    if (NOMORE())
        corrupt("%s: lzw premature end", g.inf);
    buf += (unsigned long)NEXT() << 8;
    final = prev = buf & mask;
    buf >>= bits;
    left = 16 - bits;
    if (prev > 255)
        corrupt("%s: invalid lzw code", g.inf);
    obuf[0] = (unsigned char)final;
    outcnt = 1;

    stack = 0;
    for (;;) {
        if (end >= mask && bits < max) {
            unsigned rem = (unsigned)((in_pos() - mark) % bits);
            if (rem) {
                rem = bits - rem;
                if (NOMORE())
                    break;
                while (rem > in_left) {
                    rem -= (unsigned)in_left;
                    in_left = 0;
                    if (load() == 0)
                        corrupt("%s: lzw premature end", g.inf);
                }
                in_left -= rem;
                in_next += rem;
            }
            buf = 0;
            left = 0;
            mark = in_pos();
            bits++;
            mask <<= 1;
            mask++;
        }

        if (NOMORE())
            break;
        buf += (unsigned long)NEXT() << left;
        left += 8;
        if (left < bits) {
            if (NOMORE())
                corrupt("%s: lzw premature end", g.inf);
            buf += (unsigned long)NEXT() << left;
            left += 8;
        }
        code = buf & mask;
        buf >>= bits;
        left -= bits;

        if (code == 256 && flags) {
            unsigned rem = (unsigned)((in_pos() - mark) % bits);
            if (rem) {
                rem = bits - rem;
                while (rem > in_left) {
                    rem -= (unsigned)in_left;
                    in_left = 0;
                    if (load() == 0)
                        corrupt("%s: lzw premature end", g.inf);
                }
                in_left -= rem;
                in_next += rem;
            }
            buf = 0;
            left = 0;
            mark = in_pos();
            bits = 9;
            mask = 0x1ff;
            end = 255;
            continue;
        }

        {
            unsigned temp = code;
            if (code > end) {
                if (code != end + 1 || prev > end)
                    corrupt("%s: invalid lzw code", g.inf);
                match[stack++] = (unsigned char)final;
                code = prev;
            }
            while (code >= 256) {
                match[stack++] = suffix[code];
                code = prefix[code];
            }
            match[stack++] = (unsigned char)code;
            final = code;
            if (end < mask) {
                end++;
                prefix[end] = (unsigned short)prev;
                suffix[end] = (unsigned char)final;
            }
            prev = temp;
        }

        while (stack > WSIZE - outcnt) {
            while (outcnt < WSIZE)
                obuf[outcnt++] = match[--stack];
            out_data(obuf, outcnt);
            outcnt = 0;
        }
        do {
            obuf[outcnt++] = match[--stack];
        } while (stack);
    }
    out_data(obuf, outcnt);
#undef NOMORE
#undef NEXT
}

/* ---- listing ---------------------------------------------------------- */

#define NAMEMAX1 48
#define NAMEMAX2 16

void show_info(int method, unsigned long check, int64_t len, int cont)
{
    size_t max, n;
    char tag[NAMEMAX1 + 1];
    char mod[64];
    time_t now;

    max = g.verbosity > 1 ? NAMEMAX2 : NAMEMAX1;
    memset(tag, 0, max + 1);
    if (cont == 2)
        strncpy(tag, "(total)", max + 1);
    else if (cont)
        strncpy(tag, "<...>", max + 1);
    else if (g.hname == NULL) {
        n = strlen(g.inf) - pz_suffix_len(g.inf);
        memcpy(tag, g.inf, n > max + 1 ? max + 1 : n);
        if (strcmp(g.inf + n, ".tgz") == 0 && n < max + 1)
            strncpy(tag + n, ".tar", max + 1 - n);
    }
    else
        strncpy(tag, g.hname, max + 1);
    if (tag[max])
        strcpy(tag + max - 3, "...");

    if (g.stamp && !cont) {
        time_t st = g.stamp;
        char *c = ctime(&st);
        if (c == NULL)
            strcpy(mod, "??? ??? ?? ??:??:?? ????\n");
        else
            snprintf(mod, sizeof(mod), "%s", c);
        now = time(NULL);
        c = ctime(&now);
        if (c != NULL && strlen(mod) >= 20 && strcmp(mod + 20, c + 20) != 0)
            memmove(mod + 11, mod + 19, strlen(mod + 19) + 1);
    }
    else
        strcpy(mod + 4, "------ -----");
    mod[16] = 0;

    if (g.first) {
        if (g.verbosity > 1)
            fputs("method    check    timestamp    ", stdout);
        if (g.verbosity > 0)
            puts("compressed   original reduced  name");
        g.first = 0;
    }

    if (g.verbosity > 1) {
        if (cont == 2)
            printf("        %08lx                ", check);
        else if (g.form == 3 && !g.decode)
            printf("zip%3d  --------  %s  ", method, mod + 4);
        else if (g.form > 1)
            printf("zip%3d  %08lx  %s  ", method, check, mod + 4);
        else if (g.form == 1)
            printf("zlib%2d  %08lx  %s  ", method, check, mod + 4);
        else if (method == 257)
            printf("lzw     --------  %s  ", mod + 4);
        else
            printf("gzip%2d  %08lx  %s  ", method, check, mod + 4);
    }
    if (g.verbosity > 0) {
        double red = 100. * ((double)len - (double)in_total) / (double)len;
        if ((g.form == 3 && !g.decode && cont != 2) ||
            ((method == 8 || cont == 2) &&
             in_total > (len + (len >> 10) + 12)) ||
            (method == 257 && in_total > len + (len >> 1) + 3))
            printf("%10jd %10jd?  unk    %s\n", (intmax_t)in_total,
                   (intmax_t)len, tag);
        else
            printf("%10jd %10jd %6.1f%%  %s\n", (intmax_t)in_total,
                   (intmax_t)len, red, tag);
    }
    if (g.verbosity > 1 && g.hcomm != NULL && !cont)
        puts(g.hcomm);
}

/* list the contents of the current input (header already unread) */
void list_info(void)
{
    int method;
    int64_t at, total;
    unsigned char tail[8];
    size_t n;

    if (!g.decode)
        in_begin();
    if (!g.decode)
        method = read_header(1);
    else
        method = pz_list_method;
    if (method < 0) {
        if (method == -6)
            complain("skipping: %s corrupt: header crc error", g.inf);
        else if (method == -1)
            complain("skipping: %s empty", g.inf);
        else
            complain("skipping: %s unrecognized format", g.inf);
        return;
    }

    if (g.form > 1) {
        in_total = (int64_t)g.zip_clen;
        show_info(method, g.zip_crc, (int64_t)g.zip_ulen, 0);
        return;
    }

    /* read the rest, keeping the last eight bytes */
    at = in_pos();
    n = 0;
    memset(tail, 0, sizeof(tail));
    for (;;) {
        if (in_left == 0 && load() == 0)
            break;
        if (in_left >= 8) {
            memcpy(tail, in_next + in_left - 8, 8);
            n = 8;
        }
        else {
            size_t keep = 8 - in_left;
            if (keep > n)
                keep = n;
            memmove(tail, tail + n - keep, keep);
            memcpy(tail + keep, in_next, in_left);
            n = keep + in_left;
        }
        in_next += in_left;
        in_left = 0;
    }
    total = in_total;

    if (g.form == 1) {
        unsigned long check = 0;
        size_t i, k = n < 4 ? n : 4;
        for (i = n - k; i < n; i++)
            check = (check << 8) + tail[i];
        in_total = total - 6;
        show_info(method, check & LOW32, 0, 0);
        return;
    }
    if (method == 257) {
        in_total = total - 3;
        show_info(method, 0, 0, 0);
        return;
    }
    if (total - at < 8) {
        complain("skipping: %s not a valid gzip file", g.inf);
        return;
    }
    in_total = total - at - 8;
    if (in_total < 2) {
        complain("skipping: %s not a valid gzip file", g.inf);
        return;
    }
    {
        unsigned char *t = tail + n - 8;
        unsigned long check = t[0] + ((unsigned long)t[1] << 8) +
                              ((unsigned long)t[2] << 16) +
                              ((unsigned long)t[3] << 24);
        unsigned long len = t[4] + ((unsigned long)t[5] << 8) +
                            ((unsigned long)t[6] << 16) +
                            ((unsigned long)t[7] << 24);
        show_info(method, check, (int64_t)len, 0);
    }
}
