/* infl_run.c -- deflate decoding into a 32K window that is written out each
   time it fills, pulling input through a refill callback */
#include <string.h>
#include "infl.h"

#define WBITS 15
#define WSZ (1U << WBITS)

enum { M_TYPE, M_STORED, M_TABLE, M_LEN, M_DONE, M_BAD };

struct infstate {
    int mode, last;
    unsigned length, offset, extra;
    unsigned nlen, ndist, ncode, have;
    unsigned whave;
    const hcode *lencode, *distcode;
    unsigned lenbits, distbits;
    hcode *next;
    unsigned short lens[320];
    unsigned short work[288];
    hcode codes[852 + 592];
};

static hcode fixed_codes[544];
static const hcode *fixed_len, *fixed_dist;

static void fixed_tables(void)
{
    static int built = 0;
    if (!built) {
        unsigned short lens[320], work[288];
        unsigned sym = 0, bits;
        hcode *next;
        while (sym < 144) lens[sym++] = 8;
        while (sym < 256) lens[sym++] = 9;
        while (sym < 280) lens[sym++] = 7;
        while (sym < 288) lens[sym++] = 8;
        next = fixed_codes;
        fixed_len = next;
        bits = 9;
        build_table(T_LENS, lens, 288, &next, &bits, work);
        sym = 0;
        while (sym < 32) lens[sym++] = 5;
        fixed_dist = next;
        bits = 5;
        build_table(T_DISTS, lens, 32, &next, &bits, work);
        built = 1;
    }
}

/* the fast decoding loop, used when at least 6 input bytes and 258 bytes of
   window space are available */
static void fast_loop(struct infstate *st, unsigned char *window,
                      const unsigned char **pnext, unsigned *phave,
                      unsigned char **pput, unsigned *pleft,
                      unsigned long *phold, unsigned *pbits, const char **msg)
{
    const unsigned char *in = *pnext, *last;
    unsigned char *out = *pput, *beg, *end;
    unsigned wsize = WSZ, whave = st->whave;
    unsigned long hold = *phold;
    unsigned bits = *pbits;
    const hcode *lcode = st->lencode, *dcode = st->distcode;
    unsigned lmask = (1U << st->lenbits) - 1;
    unsigned dmask = (1U << st->distbits) - 1;
    hcode here;
    unsigned op, len, dist;
    unsigned char *from;

    last = in + (*phave - 5);
    beg = out - (wsize - *pleft);
    end = out + (*pleft - 257);

    do {
        if (bits < 15) {
            hold += (unsigned long)(*in++) << bits;
            bits += 8;
            hold += (unsigned long)(*in++) << bits;
            bits += 8;
        }
        here = lcode[hold & lmask];
      dolen:
        op = here.bits;
        hold >>= op;
        bits -= op;
        op = here.op;
        if (op == 0) {
            *out++ = (unsigned char)here.val;
        }
        else if (op & 16) {
            len = here.val;
            op &= 15;
            if (op) {
                if (bits < op) {
                    hold += (unsigned long)(*in++) << bits;
                    bits += 8;
                }
                len += (unsigned)hold & ((1U << op) - 1);
                hold >>= op;
                bits -= op;
            }
            if (bits < 15) {
                hold += (unsigned long)(*in++) << bits;
                bits += 8;
                hold += (unsigned long)(*in++) << bits;
                bits += 8;
            }
            here = dcode[hold & dmask];
          dodist:
            op = here.bits;
            hold >>= op;
            bits -= op;
            op = here.op;
            if (op & 16) {
                dist = here.val;
                op &= 15;
                if (bits < op) {
                    hold += (unsigned long)(*in++) << bits;
                    bits += 8;
                    if (bits < op) {
                        hold += (unsigned long)(*in++) << bits;
                        bits += 8;
                    }
                }
                dist += (unsigned)hold & ((1U << op) - 1);
                hold >>= op;
                bits -= op;
                op = (unsigned)(out - beg);
                if (dist > op) {
                    op = dist - op;
                    (void)whave;    /* distance checks are not enforced here */
                    from = window + wsize - op;
                    if (op < len) {
                        len -= op;
                        do {
                            *out++ = *from++;
                        } while (--op);
                        from = out - dist;
                    }
                    while (len > 2) {
                        *out++ = *from++;
                        *out++ = *from++;
                        *out++ = *from++;
                        len -= 3;
                    }
                    if (len) {
                        *out++ = *from++;
                        if (len > 1)
                            *out++ = *from++;
                    }
                }
                else {
                    from = out - dist;
                    do {
                        *out++ = *from++;
                        *out++ = *from++;
                        *out++ = *from++;
                        len -= 3;
                    } while (len > 2);
                    if (len) {
                        *out++ = *from++;
                        if (len > 1)
                            *out++ = *from++;
                    }
                }
            }
            else if ((op & 64) == 0) {
                here = dcode[here.val + (hold & ((1U << op) - 1))];
                goto dodist;
            }
            else {
                *msg = "invalid distance code";
                st->mode = M_BAD;
                break;
            }
        }
        else if ((op & 64) == 0) {
            here = lcode[here.val + (hold & ((1U << op) - 1))];
            goto dolen;
        }
        else if (op & 32) {
            st->mode = M_TYPE;
            break;
        }
        else {
            *msg = "invalid literal/length code";
            st->mode = M_BAD;
            break;
        }
    } while (in < last && out < end);

    len = bits >> 3;
    in -= len;
    bits -= len << 3;
    hold &= (1UL << bits) - 1;

    *phave = (unsigned)(in < last ? 5 + (last - in) : 5 - (in - last));
    *pleft = (unsigned)(out < end ? 257 + (end - out) : 257 - (out - end));
    *pnext = in;
    *pput = out;
    *phold = hold;
    *pbits = bits;
}

static struct infstate S;

/* decode one raw deflate stream: refill() supplies more input (returning 0
   at end of input), flush() takes a full window -- returns 1 at end of
   stream, 0 on invalid data (with *msg set), -1 if the input ran out */
int infl_run(unsigned char *window, const unsigned char **pnext,
             unsigned *phave, unsigned (*refill)(const unsigned char **),
             void (*flush)(unsigned char *, unsigned), const char **msg)
{
    struct infstate *st = &S;
    const unsigned char *next = *pnext;
    unsigned have = *phave;
    unsigned char *put = window;
    unsigned left = WSZ;
    unsigned long hold = 0;
    unsigned bits = 0;
    unsigned copy, len;
    unsigned char *from;
    hcode here, last;
    int ret;
    static const unsigned short order[19] =
        {16, 17, 18, 0, 8, 7, 9, 6, 10, 5, 11, 4, 12, 3, 13, 2, 14, 1, 15};

#define PULL() do { if (have == 0) { have = refill(&next); \
        if (have == 0) { next = 0; ret = -1; goto leave; } } } while (0)
#define PULLBYTE() do { PULL(); have--; \
        hold += (unsigned long)(*next++) << bits; bits += 8; } while (0)
#define NEEDBITS(n) do { while (bits < (unsigned)(n)) PULLBYTE(); } while (0)
#define BITS(n) ((unsigned)hold & ((1U << (n)) - 1))
#define DROPBITS(n) do { hold >>= (n); bits -= (unsigned)(n); } while (0)
#define INITBITS() do { hold = 0; bits = 0; } while (0)
#define BYTEBITS() do { hold >>= bits & 7; bits -= bits & 7; } while (0)
#define ROOM() do { if (left == 0) { put = window; left = WSZ; \
        st->whave = left; flush(put, left); } } while (0)

    *msg = 0;
    st->mode = M_TYPE;
    st->last = 0;
    st->whave = 0;

    for (;;)
        switch (st->mode) {
        case M_TYPE:
            if (st->last) {
                BYTEBITS();
                st->mode = M_DONE;
                break;
            }
            NEEDBITS(3);
            st->last = BITS(1);
            DROPBITS(1);
            switch (BITS(2)) {
            case 0:
                st->mode = M_STORED;
                break;
            case 1:
                fixed_tables();
                st->lencode = fixed_len;
                st->lenbits = 9;
                st->distcode = fixed_dist;
                st->distbits = 5;
                st->mode = M_LEN;
                break;
            case 2:
                st->mode = M_TABLE;
                break;
            case 3:
                *msg = "invalid block type";
                st->mode = M_BAD;
            }
            DROPBITS(2);
            break;

        case M_STORED:
            BYTEBITS();
            NEEDBITS(32);
            if ((hold & 0xffff) != ((hold >> 16) ^ 0xffff)) {
                *msg = "invalid stored block lengths";
                st->mode = M_BAD;
                break;
            }
            st->length = (unsigned)hold & 0xffff;
            INITBITS();
            while (st->length != 0) {
                copy = st->length;
                PULL();
                ROOM();
                if (copy > have) copy = have;
                if (copy > left) copy = left;
                memcpy(put, next, copy);
                have -= copy;
                next += copy;
                left -= copy;
                put += copy;
                st->length -= copy;
            }
            st->mode = M_TYPE;
            break;

        case M_TABLE:
            NEEDBITS(14);
            st->nlen = BITS(5) + 257;
            DROPBITS(5);
            st->ndist = BITS(5) + 1;
            DROPBITS(5);
            st->ncode = BITS(4) + 4;
            DROPBITS(4);
            if (st->nlen > 286 || st->ndist > 30) {
                *msg = "too many length or distance symbols";
                st->mode = M_BAD;
                break;
            }
            st->have = 0;
            while (st->have < st->ncode) {
                NEEDBITS(3);
                st->lens[order[st->have++]] = (unsigned short)BITS(3);
                DROPBITS(3);
            }
            while (st->have < 19)
                st->lens[order[st->have++]] = 0;
            st->next = st->codes;
            st->lencode = st->next;
            st->lenbits = 7;
            if (build_table(T_CODES, st->lens, 19, &st->next, &st->lenbits,
                            st->work)) {
                *msg = "invalid code lengths set";
                st->mode = M_BAD;
                break;
            }
            st->have = 0;
            while (st->have < st->nlen + st->ndist) {
                for (;;) {
                    here = st->lencode[BITS(st->lenbits)];
                    if ((unsigned)here.bits <= bits) break;
                    PULLBYTE();
                }
                if (here.val < 16) {
                    DROPBITS(here.bits);
                    st->lens[st->have++] = here.val;
                }
                else {
                    if (here.val == 16) {
                        NEEDBITS(here.bits + 2);
                        DROPBITS(here.bits);
                        if (st->have == 0) {
                            *msg = "invalid bit length repeat";
                            st->mode = M_BAD;
                            break;
                        }
                        len = st->lens[st->have - 1];
                        copy = 3 + BITS(2);
                        DROPBITS(2);
                    }
                    else if (here.val == 17) {
                        NEEDBITS(here.bits + 3);
                        DROPBITS(here.bits);
                        len = 0;
                        copy = 3 + BITS(3);
                        DROPBITS(3);
                    }
                    else {
                        NEEDBITS(here.bits + 7);
                        DROPBITS(here.bits);
                        len = 0;
                        copy = 11 + BITS(7);
                        DROPBITS(7);
                    }
                    if (st->have + copy > st->nlen + st->ndist) {
                        *msg = "invalid bit length repeat";
                        st->mode = M_BAD;
                        break;
                    }
                    while (copy--)
                        st->lens[st->have++] = (unsigned short)len;
                }
            }
            if (st->mode == M_BAD)
                break;
            if (st->lens[256] == 0) {
                *msg = "invalid code -- missing end-of-block";
                st->mode = M_BAD;
                break;
            }
            st->next = st->codes;
            st->lencode = st->next;
            st->lenbits = 9;
            if (build_table(T_LENS, st->lens, st->nlen, &st->next,
                            &st->lenbits, st->work)) {
