                            &st->next, &st->distbits, st->work)) {
                *msg = "invalid distances set";
                st->mode = M_BAD;
                break;
            }
            st->mode = M_LEN;
            /* fall through */

        case M_LEN:
            if (have >= 6 && left >= 258) {
                if (st->whave < WSZ)
                    st->whave = WSZ - left;
                fast_loop(st, window, &next, &have, &put, &left, &hold, &bits,
