            for (;;) {
                here = st->lencode[BITS(st->lenbits)];
                if ((unsigned)here.bits <= bits) break;
                PULLBYTE();
            }
            if (here.op && (here.op & 0xf0) == 0) {
                last = here;
                for (;;) {
                    here = st->lencode[last.val +
                            (BITS(last.bits + last.op) >> last.bits)];
                    if ((unsigned)(last.bits + here.bits) <= bits) break;
                    PULLBYTE();
                }
                DROPBITS(last.bits);
            }
            DROPBITS(here.bits);
            st->length = here.val;
            if (here.op == 0) {
                ROOM();
                *put++ = (unsigned char)st->length;
                left--;
                st->mode = M_LEN;
                break;
            }
            if (here.op & 32) {
                st->mode = M_TYPE;
                break;
            }
            if (here.op & 64) {
                *msg = "invalid literal/length code";
                st->mode = M_BAD;
                break;
