                last = here;
                for (;;) {
                    here = st->distcode[last.val +
                            (BITS(last.bits + last.op) >> last.bits)];
                    if ((unsigned)(last.bits + here.bits) <= bits) break;
                    PULLBYTE();
                }
                DROPBITS(last.bits);
            }
            DROPBITS(here.bits);
            if (here.op & 64) {
                *msg = "invalid distance code";
                st->mode = M_BAD;
                break;
            }
            st->offset = here.val;
            st->extra = here.op & 15;
            if (st->extra != 0) {
                NEEDBITS(st->extra);
                st->offset += BITS(st->extra);
                DROPBITS(st->extra);
            }
            if (st->offset > WSZ - (st->whave < WSZ ? left : 0)) {
                *msg = "invalid distance too far back";
                st->mode = M_BAD;
                break;
            }
            do {
                ROOM();
                copy = WSZ - st->offset;
                if (copy < left) {
                    from = put + copy;
                    copy = left - copy;
                }
                else {
                    from = put - st->offset;
                    copy = left;
                }
                if (copy > st->length) copy = st->length;
                st->length -= copy;
                left -= copy;
                do {
                    *put++ = *from++;
                } while (--copy);
            } while (st->length != 0);
            break;

        case M_DONE:
            ret = 1;
            if (left < WSZ)
                flush(window, WSZ - left);
            goto leave;

        case M_BAD:
            ret = 0;
            goto leave;
        }

  leave:
    *pnext = next;
    *phave = have;
    return ret;
}
